window.PAKET_FW_FUEHRERSCHEIN = {"id": "fw-fuehrerschein", "titel": "Feuerwehrführerschein — Prüfungsgespräch", "untertitel": "Führerscheinausbildung · OÖ", "farbe": "#4d7c0f", "beschreibung": "Feuerwehrführerschein (Klasse C für Feuerwehrfahrzeuge): der komplette offizielle Fragenkatalog zur Vorbereitung auf das Prüfungsgespräch aus dem OÖLFV-Ausbildungsplan (6.11.002) — Grundlagen, Technisches, Feuerwehrspezifisches und Rechtliches, inkl. Merkhilfen zur 12 Fahrlektionen-Ausbildung.", "meta": {"zielgruppe": "aktiv"}, "po": {"pruefungsgespraech": "Vor der Prüfungsfahrt: Prüfungsgespräch mit 4 Themen (§ 3 Abs. 2 FSG-FRV): kraftfahrrechtliche/straßenpolizeiliche Bestimmungen für Einsatzfahrzeuge · Fahrzeugtechnik (Fehlererkennung, -begrenzung, Wartung) · Fahrphysik von Feuerwehrfahrzeugen · Absicherung und richtiges Verhalten am Einsatzort", "ausbildung": "12 Einheiten Theorie in der Fahrschule · 2 Fahrlektionen in der Fahrschule (mit internem Fahrausbilder) · 10 Fahrlektionen mit dem Feuerwehrfahrzeug über 7,5 t hzG", "pruefungsfahrt": "mind. 45 Minuten mit Feuerwehrfahrzeug über 7.500 kg hzG: Überprüfungen, Fahrübungen, Bremsübungen — Prüfung immer Samstag, 85 € Gebühr", "bestehen": "Prüfungsgespräch positiv UND Prüfungsfahrt bestanden — Feuerwehrführerschein danach über syBOS beantragen (Prüfungsprotokoll, Führerschein, Passfoto)", "quelle": "Ausbildungsplan Feuerwehrführerschein (6.11.002, inkl. Lernunterlage Fragenkatalog Prüfungsgespräch, September 2020) + RL Führerscheinausbildung im Feuerwehrwesen (6.11.001)"}, "fragen": [{"m": "Grundlagen", "src": "Grundlagen", "f": "Was ist beim Schutzweg verboten?", "opts": ["Das Überholen auf und unmittelbar vor ungeregelten Schutzwegen · das Vorbeifahren an Fahrzeugen, die angehalten haben, um Fußgänger überqueren zu lassen · das Halten und Parken auf der Bodenmarkierung · das Halten und Parken in den letzten 5 m vor der Bodenmarkierung aus der Sicht des ankommenden Verkehrs · bei Kolonnenverkehr darf man auf dem Übergang nicht anhalten.", "Das Befahren mit Blaulicht ohne Folgetonhorn", "Das Parken 10 m nach dem Schutzweg", "Das Überholen mit mehr als 30 km/h"], "r": 0, "e": "", "m2": "Grundlagen"}, {"m": "Grundlagen", "src": "Grundlagen", "f": "Wo müssen Sie vermehrt mit Kindern rechnen?", "opts": ["Im Bereich von Kindergärten, Schulen und Kinderspielplätzen.", "Auf Autobahnen", "In Industriegebieten", "An Kreuzungen mit Ampeln"], "r": 0, "e": "", "m2": "Grundlagen"}, {"m": "Grundlagen", "src": "Grundlagen", "f": "Wie werden Sie sich als Fahrzeuglenker gegenüber Kindern verhalten?", "opts": ["Ich richte meine Aufmerksamkeit verstärkt auf diese und fahre, falls notwendig, auch bremsbereit · ich fahre so, dass ich etwaige Fehler von Kindern ausgleichen kann · ich rechne damit, dass sie sich nicht situationsgerecht verhalten werden.", "Ich hupue, damit die Kinder weglaufen", "Ich fahre schnell vorbei, um keine Zeit zu verlieren", "Kinder weichen immer zuverlässig aus — ich fahre normal weiter"], "r": 0, "e": "", "m2": "Grundlagen"}, {"m": "Grundlagen", "src": "Grundlagen", "f": "Wie werden Sie sich als Fahrzeuglenker gegenüber älteren oder gebrechlichen Verkehrsteilnehmern verhalten?", "opts": ["Ich beobachte verstärkt das Verhalten dieser Personen und fahre, falls notwendig, auch bremsbereit · ich fahre so, dass ich etwaige Fehler ausgleichen kann.", "Ich überhole sofort, um den Verkehr nicht zu behindern", "Ich schalte das Folgetonhorn ein, damit sie schneller gehen", "Ältere Menschen haben Vorrang — ich halte immer an"], "r": 0, "e": "", "m2": "Grundlagen"}, {"m": "Grundlagen", "src": "Grundlagen", "f": "Wie ist der Abstand zum vorderen Fahrzeug (im Nichteinsatzfall) zu wählen?", "opts": ["Ca. 2–3 Sekunden oder ca. 50 m Abstand halten, denn wenn mich ein Fahrzeug überholt, dann kann es sich vor mir einordnen.", "Ca. 5 Meter, um Platz für Überholende zu lassen", "So nah wie möglich, um den Verkehrsfluss zu erhalten", "Mindestens 100 m auf allen Straßen"], "r": 0, "e": "", "m2": "Grundlagen"}, {"m": "Technisches", "src": "Technisches", "f": "Welche Kontrollen führen Sie bei Reifen vor Fahrtantritt durch?", "opts": ["Die Verformung des Reifens durch Sichtkontrolle prüfen · die Gleichmäßigkeit der Laufflächenabnützung", "Das Fabrikat und die Farbe der Reifen", "Den Reifendruck nur bei der Werkstatt", "Das Herstellungsdatum der Räder"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Wie viel mm muss die Profiltiefe mindestens haben?", "opts": ["Mind. 2 mm", "Mind. 1,6 mm", "Mind. 4 mm", "Mind. 8 mm"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Welche Nachteile und Gefahren kann es beim Fahren mit zu geringem Reifendruck geben?", "opts": ["Überhitzung des Reifens durch starkes Walken · Reifenbrand oder -platzer · Erhöhung des Kraftstoffverbrauches", "Höhere Endgeschwindigkeit", "Kürzere Bremswege", "Bessere Kurvenlage"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Wo darf man einen Radwechsel durchführen und was muss man beachten?", "opts": ["Es ist ein geeigneter Platz zu suchen, nicht auf der Fahrbahn! · Alarmblinkanlage einschalten · Warnweste anziehen · Feststellbremse anziehen, Gang einlegen, Unterlegkeile vorlegen · Radmuttern lockern · Fahrzeug abheben · Radmuttern abschrauben · Rad oder Räder abnehmen · Reserverad aufsetzen (beim Aufsetzen der Zwillingsräder ist auf den Ventilzugang zu achten) · Radmuttern anschrauben · Radmuttern kreuzweise festziehen", "Überall — Hauptsache schnell", "Nur auf Parkplätzen mit Werkstatteinrichtung", "Auf der Fahrbahn mit eingeschaltetem Blaulicht"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Was ist eine Feststellbremse?", "opts": ["Es ist eine von der Betriebsbremse unabhängig zu betätigende Bremsanlage, mit der das Abrollen des Fahrzeuges dauernd verhindert werden kann.", "Die Bremse, die nur beim Rangieren verwendet wird", "Ein zusätzliches Bremssystem für den Anhänger", "Die Handbremse der Betriebsbremse"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Was können Sie an der Betriebsbremse bei stehendem Fahrzeug überprüfen?", "opts": ["Den Leerweg, die Dichtheit, die Bremslichter und das Mehrkreisschutzventil", "Die Bremswirkung bei Vollbremsung", "Die Abstimmung der Antiblockiervorrichtung", "Die Funktion des Bremskraftverstärkers bei laufendem Motor"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Was ist bei einer Lenkung regelmäßig zu kontrollieren?", "opts": ["Der Flüssigkeitsstand im Ölbehälter der hydraulischen Lenkhilfe · das Lenkungsspiel, bei laufendem Motor darf kein deutlicher Leerweg spürbar sein · die Leichtgängigkeit · der Selbstrücklauf", "Nur die Farbe des Lenkölles", "Nichts — die Lenkung ist wartungsfrei", "Nur den Zustand des Lenkrad-Bezuges"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Ihr LKW zieht beim Geradeausfahren nach einer Seite. Welche Ursachen kann dies haben?", "opts": ["Zu geringer Reifendruck in einem der beiden Vorderreifen · die Lenkgeometrie ist verstellt · starker Seitenwind", "Defekte Lichtmaschine", "Zu viel Motoröl", "Verschlissene Kupplung"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Welche Wartungs- und Kontrollarbeiten kann der Lenker an der Batterie selbst durchführen?", "opts": ["Kontrolle des Flüssigkeitsstandes · Säubern der Pole · Kabelanschlüsse und Batteriehalterungen auf festen Sitz prüfen", "Das Aufladen mit Schnellladegeräten in der Werkstätte", "Die Neuerstellung der Batterie-Dokumentation", "Elektrolyt selbst nachfüllen und mischen"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Welche Auswirkungen kann eine rutschende Kupplung auf den Fahrbetrieb haben?", "opts": ["Die Beschleunigung des Fahrzeuges wird schlechter · die Motorbremsung wird geringer · die Wirkung der Motorstaubremse ist geringer", "Der Kraftstoffverbrauch sinkt", "Der Öldruck steigt", "Die Geschwindigkeit erhöht sich"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Was kann der Lenker an der Kupplung überprüfen?", "opts": ["Den Leerweg (Totgang) · das vollständige Lösen · das vollständige Verbinden", "Den Verschleiß der Kupplungsscheibe in Millimetern", "Die Qualität des Kupplungsöles", "Nichts — die Kupplung ist verschlossen"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Welche Kaltstarteinrichtungen können bei einem Dieselmotor eingebaut sein?", "opts": ["Flammstartanlage · Heizflansch · Vorglühanlage", "Choke-Klappe", "Anlasser mit Überhöhung", "Glühkerzen für den Sommerbetrieb"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Woran können Sie eine Störung in der Kaltstarteinrichtung des Dieselmotors erkennen?", "opts": ["Motor springt nicht an · beim Verglühen leuchtet die Vorglüh-Kontrolllampe nicht auf.", "Der Motor läuft unregelmäßig bei Warmbetrieb", "Die Wasserpumpe rasselt", "Der Keilriemen quietscht"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Woran können Sie während der Fahrt Mängel im Schmiersystem des Dieselmotors erkennen?", "opts": ["Am Ölmanometer oder an der Öldruckkontrolllampe", "Am Fernthermometer", "Am Drehzahlmesser", "Am Kilometerzähler"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Während der Fahrt leuchtet die Öldruckkontrolllampe auf. Wie werden Sie sich verhalten?", "opts": ["Ich halte an und stelle den Motor ab · wenn genügend Motoröl in der Ölwanne ist, lasse ich den LKW abschleppen.", "Ich fahre mit halber Geschwindigkeit weiter bis zur Werkstätte", "Ich füge während der Fahrt Öl nach", "Ich ignoriere die Lampe — sie leuchtet bei jedem Start"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Während der Fahrt leuchtet die Ladekontrollleuchte auf. Was schließen Sie daraus und wie verhalten Sie sich?", "opts": ["Strom wird nur mehr aus der Batterie entnommen · die Batterie wird nicht mehr geladen · ich kontrolliere den Keilriemen · wenn der Keilriemen nicht gerissen ist, fahre ich zur nächsten Werkstätte.", "Der Akku ist überladen — ich schalte Verbraucher zu", "Die Lichtanlage hat einen Masseschluss", "Es liegt keine Störung vor — die Lampe leuchtet im Normalbetrieb"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Wie können Sie während der Fahrt feststellen, dass die Motorkühlung nicht einwandfrei funktioniert?", "opts": ["Das Fernthermometer zeigt in den roten Bereich · eine zusätzliche Kühlerkontrolllampe beim Fernthermometer leuchtet auf.", "Am Öldruck", "Am Ladedruckmesser", "Am Tachometer"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Wie verhalten Sie sich, wenn Sie erkennen, dass die Motorkühlung ausgefallen ist?", "opts": ["Ich werde anhalten und kontrollieren, ob der Keilriemen richtig gespannt ist · ich kontrolliere, ob genügend Kühlflüssigkeit im Ausgleichsbehälter ist.", "Ich fahre weiter, bis der Motor von selbst ausgeht", "Ich öffne sofort den Kühlerverschluss bei heißem Motor", "Ich schalte die Heizung aus, um den Motor zu kühlen"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Wie können Sie während der Fahrt feststellen, dass die Betriebsbremse defekt ist?", "opts": ["Die Bremswarnleuchte leuchtet auf · ich bemerke eine verringerte oder fehlende Bremswirkung.", "Am Bremspedal-Geruch allein", "Am unruhigen Motorlauf", "Am Fahrverhalten in Kurven"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Wie verhalten Sie sich, wenn Sie einen Defekt an der Betriebsbremse feststellen?", "opts": ["Ich halte an und führe eine Standbremsprobe durch.", "Ich fahre im Kriechgang weiter", "Ich nutze nur noch die Motorbremse", "Ich melde den Mangel erst am Ende der Fahrt"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Welche Vorteile hat die Luftfederung?", "opts": ["Schonung des Ladegutes · beim Kurvenfahren bleibt die Ladefläche nahezu waagrecht.", "Kürzere Bremswege", "Geringeres Fahrzeuggewicht", "Höhere Zuladung"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Was können Sie an der Luftfederung eines LKW überprüfen?", "opts": ["Den Zustand der Federbälge durch Sichtkontrolle · die Dichtheit durch Abhorchen · das Gestänge der Niveauregelventile", "Den Luftdruck im Federbalg mit dem Reifendruckprüfer", "Die Farbe der Federbälge", "Nichts — die Luftfederung ist wartungsfrei"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Welche Ursachen kann blauer Auspuffrauch haben?", "opts": ["Hoher Verschleiß am Motor · Ölabstreifring gebrochen · Dichtring undicht", "Luftfilter stark verschmutzt", "Treibstoffüberschuss", "Motor überlastet"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Welche Ursachen kann schwarzer Auspuffrauch haben?", "opts": ["Luftfilter stark verschmutzt · Treibstoffüberschuss · Motor überlastet", "Ölabstreifring gebrochen", "Wasserdampf nach Kaltstart", "Zylinderkopfdichtung undicht"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Welche Ursachen kann weißer Auspuffrauch haben?", "opts": ["Wasserdampf nach Kaltstart · Zylinderkopfdichtung undicht, defekt · Steg- oder Büchsenriss im Motorzylinder", "Motor überlastet", "Treibstoffüberschuss", "Hoher Verschleiß am Motor"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Wozu dient das Mehrkreisschutzventil bei einer Druckluftbremse?", "opts": ["Zur Drucksicherung von Nebenverbrauchern · zur Erhaltung des Sicherungsdruckes bei Ausfall eines Kreises der Betriebsbremsanlage", "Zur Erhöhung des Bremsdruckes bei Vollbremsung", "Zum automatischen Entfeuchten der Luftbehälter", "Zur Regelung der Bremskraft je Achse nach Beladung"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Welche Aufgabe hat das Mehrkreisschutzventil einer Druckluftbremse?", "opts": ["Es sichert den Druck in den anderen Vorratskreisen, wenn ein Vorratskreis ausfällt.", "Es verteilt die Druckluft gleichmäßig auf alle Bremsen", "Es begrenzt den Druck im Bremszylinder auf 2 bar", "Es überwacht den Luftdruck im Fahrbetrieb"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Was verstehen Sie unter einer ALB-Regelung bei einer Druckluftbremsanlage?", "opts": ["Eine Anlage, welche die Bremskraft der Achsen nach dem Beladungszustand automatisch regelt.", "Eine Anlage zur automatischen Leerlauf-Bremse", "Die automatische Leckstellenerkennung", "Die Abstimmung von Bremskraft und Geschwindigkeit"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Wie durchfahren Sie eine Kurve mit dem LKW?", "opts": ["Ich werde vor der Kurve die Geschwindigkeit anpassen und erst im Kurvenauslauf beschleunigen · in der Kurve mache ich kurze Kontrollblicke in den Rückspiegel.", "Ich fahre mit gleichbleibender Geschwindigkeit durch die Kurve", "Ich bremse erst in der Kurve ab", "Ich beschleunige am Kurveneingang, um Untersteuern zu vermeiden"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Sie fahren mit Ihrem LKW in eine Kurve. Welche Faktoren erhöhen die Kippgefahr?", "opts": ["Eine verrutschende Ladung · eine hohe Schwerpunktlage · ruckartiges Lenken · halbvoller Wassertank", "Ein voller Wassertank", "Tiefer Schwerpunkt", "Langsames Fahren"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Wonach richten Sie die Fahrgeschwindigkeit in einer engen Kurve?", "opts": ["Nach dem Kurvenradius und der Querneigung der Fahrbahn · nach der Höhe des Gesamtschwerpunktes des LKW · nach dem Fahrbahnzustand", "Nach der Ausschilderung der zulässigen Höchstgeschwindigkeit allein", "Nach der Verkehrsdichte", "Nach dem Zustand der Ladungssicherung"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Sie befahren mit Ihrem LKW eine längere Gefällestrecke. Wann verwenden Sie die Betriebsbremse?", "opts": ["Vor und während des Zurückschaltens in einen niedrigen Gang · zum Anbremsen vor Kurven · beim Anbremsen bis zum Stillstand", "Dauerhaft auf der ganzen Strecke", "Nur im Falle einer Notbremsung", "Erst am Ende der Gefällestrecke"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Sie fahren mit Ihrem LKW auf einer Freilandstraße mit einem Gefälle von 9 %. Wie verhalten Sie sich in dieser Situation?", "opts": ["Ich werde rechtzeitig auf einen niedrigen Gang schalten, damit ich mit der Motorbremswirkung meine Geschwindigkeit halten kann · ich bremse mit der Motorstaubremse auch über eine längere Strecke · falls vorhanden, bremse ich mit der Wirbelstrombremse.", "Ich bremse mit der Betriebsbremse, wann immer die Geschwindigkeit zu hoch wird", "Ich schalte den Motor aus und rolle aus", "Ich nehme die Kurven mit Vollgas, um Schwung zu sparen"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Sie befahren mit Ihrem LKW eine Steigung. Wann müssen Sie zurückschalten?", "opts": ["Wenn die Motordrehzahl trotz Vollgas unter den „grünen Bereich“ des Drehzahlmessers zu sinken droht.", "Erst wenn der Motor ausgeht", "Nie — der LKW hat genug Kraft", "Wenn die Geschwindigkeit unter 30 km/h sinkt"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Sie erkennen, dass sich hinter Ihrem LKW eine lange Kolonne gebildet hat. Wie werden Sie sich im Nichteinsatzfall verhalten?", "opts": ["Ich sollte an geeigneter Stelle anhalten und die Fahrzeuge hinter mir vorbeizulassen · ich werde auf die Fahrzeuge hinter mir besonders achten, um bei riskanten Überholmanövern rasch reagieren zu können.", "Ich fahre schneller, um die Kolonne aufzulösen", "Ich hupue ununterbrochen, damit niemand überholt", "Ich blende die Nachfolgenden mit dem Nebelscheinwerfer ab"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Wie erkennen Sie, dass nicht genügend Motoröl vorhanden ist?", "opts": ["Aufleuchten der Ölstandskontrolleleuchte, wenn eine vorhanden ist · bei abgestelltem Motor durch den Ölmessstab", "Am Öldruck beim Fahren", "Am Geräusch der Ventile", "Am Auspuffrauch"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Welche Gefahr besteht, wenn Sie sich bei aufleuchtender Öldruckkontrollleuchte falsch verhalten?", "opts": ["Bei Weiterfahrt kann es zu einem Motorschaden kommen · bei einem Motorschaden kann das Fahrzeug ins Schleudern kommen · wenn das Fahrzeug auf der Fahrbahn abgestellt wird und nicht abgesichert ist, kann es zu einem Auffahrunfall kommen.", "Nur ein höherer Kraftstoffverbrauch", "Nur eine Ölpest auf der Fahrbahn", "Keine Gefahr — die Lampe ist nur ein Hinweis"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Was ist beim Überholen von Fahrzeugen zu beachten?", "opts": ["Den größeren Platzbedarf berücksichtigen · unter Umständen mit längeren Bremswegen rechnen · rechtzeitig zurückschalten · mit einer geringeren Beschleunigung rechnen · den längeren Überholweg und die größere Überholsichtweite berücksichtigen · den Seitenabstand beachten, im Besonderen beim Überholen von Rad- und Mopedfahrern", "Hupen, um den Vordermann zum Ausweichen zu zwingen", "Überholen ist mit Feuerwehrfahrzeugen immer erlaubt", "Nur die Geschwindigkeit beachten"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Was verstehen Sie unter einer Druckluftbremsanlage?", "opts": ["Eine Bremsanlage, bei der die Bremskraft durch Druckluft erzeugt wird.", "Eine Bremsanlage mit ölhydraulischer Kraftübertragung", "Eine Bremsanlage, die nur mit Unterdruck arbeitet", "Eine Kombination aus mechanischer und elektrischer Bremse"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Was kann die Ursache sein, wenn der Kompressor zu wenig Luft fördert?", "opts": ["Luftfilter kann verlegt sein · Keilriemen können rutschen · der Kompressor kann Kompressionsverluste haben.", "Der Lufttrockner ist zu alt", "Das Frostschutzmittel ist aufgebraucht", "Die Bremsbeläge sind abgenutzt"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Welche Aufgabe hat der Lufttrockner einer Druckluftbremse?", "opts": ["Der vom Kompressor geförderten Luft die Feuchtigkeit zu entziehen.", "Die Druckluft zu kühlen", "Die Druckluft zu filtern und zu ölen", "Den Druck in den Behältern zu erhöhen"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Wie können Sie im Winter die Gefahr des Einfrierens einer Druckluftbremsanlage verringern?", "opts": ["Die Frostschutzeinrichtung auf Winterbetrieb stellen · die Luftbehälter täglich entwässern.", "Die Bremse mehrmals am Tag betätigen", "Das Fahrzeug im Freien abstellen, damit Feuchtigkeit entweicht", "Heißes Wasser in die Luftbehälter füllen"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Die Warnleuchte für die Betriebsbremsanlage leuchtet auf. Wie viele Bremsungen können Sie noch durchführen?", "opts": ["Noch mind. 4 Vollbremsungen", "Noch genau 1 Vollbremsung", "Noch mind. 10 Bremsungen", "Unbegrenzt viele"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Technisches", "src": "Technisches", "f": "Der Vorratsdruck einer Druckluftbremse fällt bei einer Vollbremsung um mehr als 0,7 bar ab. Welche Ursachen kann dies haben?", "opts": ["Die Bremsbeläge können abgenutzt sein · die Vorratsbehälter können stark eingebeult sein · Wasser kann in den Vorratsbehältern sein.", "Der Lufttrockner ist defekt", "Der Kompressor fördert zu viel", "Die Frostschutzeinrichtung ist auf Sommer gestellt"], "r": 0, "e": "", "m2": "Technisches"}, {"m": "Feuerwehrspezifisches", "src": "Feuerwehrspezifisches", "f": "Worauf ist beim Fahren mit Tanklöschfahrzeugen betreffend des Wassertankinhaltes zu beachten?", "opts": ["Mit vollem bzw. leerem Tank fahren, da es bei Kurvenfahrt und Bremsmanöver mit halbvollem Wassertank durch Schwabbelbewegungen zu unkontrollierbaren Schwerpunktverlagerungen kommen kann · sollte die Rückfahrt vom Einsatz mit teilgefülltem Wassertank angetreten werden, ist mit besonderer Vorsicht bis zur nächsten Füllmöglichkeit zu fahren · hohen Schwerpunkt beachten.", "Mit halbvollem Tank fahren, um Gewicht zu sparen", "Der Wasserstand hat keinen Einfluss auf die Fahrphysik", "Wasser immer erst am Einsatzort abtanken"], "r": 0, "e": "", "m2": "Feuerwehrspezifisches"}, {"m": "Feuerwehrspezifisches", "src": "Feuerwehrspezifisches", "f": "Wie sind Feuerwehrfahrzeuge verkehrs- und betriebssicher zu erhalten und wie ist dies zu überprüfen bzw. zu dokumentieren?", "opts": ["Durchführung von Probefahrten mind. alle 14 Tage über mind. 10 km mit anschließendem Eintrag ins Fahrtenbuch und Fahrzeugkontrolle anhand der Checkliste.", "Jährliche Überprüfung durch den TÜV genügt", "Probefahrten einmal im Monat über 5 km", "Fahrtenbuch wird nur bei Einsätzen geführt"], "r": 0, "e": "", "m2": "Feuerwehrspezifisches"}, {"m": "Feuerwehrspezifisches", "src": "Feuerwehrspezifisches", "f": "Wie (mit welchen Geräten) sind Einsatzstellen abzusichern?", "opts": ["Abhängig von der Witterung und den Straßenverhältnissen · im Ortsgebiet: 50 m · auf Freilandstraßen: 150–250 m · auf Autobahnen: 250–400 m. Zusätzlich zur StVO-Ausrüstung (Pannendreieck) stehen zur Verfügung: Verkehrsleitkegel · Triopan-Faltsignale · orange Blitzleuchten · hochreflektierende Warnüberwürfe · Verkehrsleiteinrichtungen am Feuerwehrfahrzeug · Verkehrsregler mit spezieller Ausrüstung (Anhaltestab, Einsatzbekleidung, Warnüberwurf).", "Immer mit 50 m Abstand — egal wo", "Mit Sirenen, die laufend betrieben werden", "Einsatzstellen müssen nicht abgesichert werden, wenn die Polizei informiert ist"], "r": 0, "e": "", "m2": "Feuerwehrspezifisches"}, {"m": "Feuerwehrspezifisches", "src": "Feuerwehrspezifisches", "f": "Wo sind Einsatzstellen abzusichern (Kurven, Kuppen)?", "opts": ["In Kurven und auf in zwei Richtungen befahrenen Straßen: Gegenverkehr sichern · vor Kuppen in ausreichendem Abstand sichern.", "Erst in der Kurve selbst sichern, damit die Absicherung den Verkehr nicht stört", "Nie absichern — die Sichtbeziehung reicht", "Nur bei Nacht absichern"], "r": 0, "e": "", "m2": "Feuerwehrspezifisches"}, {"m": "Feuerwehrspezifisches", "src": "Feuerwehrspezifisches", "f": "Was ist nach der Rückfahrt zu tun?", "opts": ["Wiederherstellen der Einsatzbereitschaft · Reinigung des Fahrzeuges · Führen des Fahrtenbuches · Kontrollen am Fahrzeug · Einrückmeldung", "Nur die Einrückmeldung — der Rest kann warten", "Fahrzeug auftanken und die Tore schließen", "Nichts — die nächste Schicht erledigt das"], "r": 0, "e": "", "m2": "Feuerwehrspezifisches"}, {"m": "Feuerwehrspezifisches", "src": "Feuerwehrspezifisches", "f": "Welche Kontrollen sind vor jeder Ausfahrt durchzuführen?", "opts": ["Einsatzbereitschaft des Fahrzeuges muss immer gegeben sein · Fahrtauglichkeit des Fahrers muss gegeben sein · Fahrzeug nicht überladen · Fahrzeugkontrolle · Abstecken der Versorgungsleitungen und der Abgasleitung · Zuteilung der Mannschaft abwarten (Fahrer ist nicht GK, GK ist nicht Fahrer) · Mindestbesatzung · Öffnen der Garagentore bis zum Anschlag / Sichern des Tores · Anlegen der Sicherheitsgurte · Fahrzeugtüren schließen · Abfahrt auf Weisung des Gruppenkommandanten", "Nur die Fahrzeugkontrolle", "Kontrollen sind nur bei Einsätzen nötig, nicht bei Übungen", "Der Maschinist erledigt alle Kontrollen allein"], "r": 0, "e": "", "m2": "Feuerwehrspezifisches"}, {"m": "Feuerwehrspezifisches", "src": "Feuerwehrspezifisches", "f": "Was ist bei der Auswahl des Aufstellungsortes bei der Einsatzstelle zu beachten?", "opts": ["Gefahrenbereich meiden · Fluchtrichtung · auf der Straßenseite der Einsatzstelle · nicht im Trümmerschatten · Rückzugsmöglichkeiten", "So nah wie möglich am Objekt, damit Schläuche sparen", "Immer auf dem Gehweg parken", "Beim Hydranten — die Wasserversorgung ist am wichtigsten"], "r": 0, "e": "", "m2": "Feuerwehrspezifisches"}, {"m": "Feuerwehrspezifisches", "src": "Feuerwehrspezifisches", "f": "Aufgabenteilung Lenker – Fahrzeugkommandant", "opts": ["Lenker: Betätigen der Warnsignale · konzentriere dich auf die Fahrt und nicht auf Funkmeldungen · Fahrgeschwindigkeit den Verhältnissen anpassen · Fahrverhalten des Fahrzeuges (hoher Schwerpunkt, Wassertank, Witterung). — Fahrzeugkommandant: Prüfen der Fahrtauglichkeit · Einweisen · Sichern · Funkverkehr · Anfahrtstrecke bekannt geben · Fahrzeugruhe.", "Der Lenker überwacht den Funk, der Kommandant fährt", "Beide teilen sich alle Aufgaben gleichmäßig", "Der Lenker entscheidet allein über die Anfahrt"], "r": 0, "e": "", "m2": "Feuerwehrspezifisches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Was versteht man unter einem Feuerwehrfahrzeug, was unter einem Einsatzfahrzeug? Ist ein VW-Golf, der auf eine Feuerwehr zugelassen ist, ein Feuerwehrfahrzeug?", "opts": ["Ein Feuerwehrfahrzeug ist ein nach Bauart und Ausrüstung ausschließlich oder vorwiegend zur Verwendung für Feuerwehren bestimmtes Fahrzeug. Ein VW Golf, der nicht entsprechend umgebaut ist, gilt nicht als Feuerwehrfahrzeug im Sinne des KFG. Ein Fahrzeug gilt als Einsatzfahrzeug, wenn entweder Blaulicht oder Folgetonhorn eingeschaltet sind, für die Dauer der Verwendung eines dieser Signale.", "Jedes auf eine Feuerwehr zugelassene Fahrzeug ist ein Feuerwehrfahrzeug im Sinne des KFG", "Ein Fahrzeug gilt nur mit Blaulicht UND Folgetonhorn als Einsatzfahrzeug", "Der VW-Golf ist ein Feuerwehrfahrzeug, wenn er die Feuerwehrfarben trägt"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Ist der Lenker eines Feuerwehrfahrzeuges auch außerhalb von Einsatzfahrzeugen an bestimmte Verkehrsvorschriften nicht gebunden?", "opts": ["Ja, bei „Allgemeines Fahrverbot“, „Einfahrt verboten“ und „Vorgeschriebene Fahrtrichtung“, wenn Ausnahmen für andere Kraftfahrzeuge und Fuhrwerke auf Zusatztafeln angebracht sind.", "Nein — Feuerwehrfahrzeuge sind nie an Verkehrsvorschriften gebunden", "Ja — auch bei Geschwindigkeitsbeschränkungen gilt das nicht", "Ja — aber nur mit eingeschaltetem Blaulicht"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Wie viele Personen dürfen Sie in einem Feuerwehrfahrzeug mitnehmen?", "opts": ["Die im Zulassungsschein eingetragene Zahl ist maßgeblich; nur bei Fahrten zu Orten eines dringenden Einsatzes und auf Rückfahrten von solchen Orten mit Feuerwehrfahrzeugen darf diese Anzahl überschritten werden (§ 106 Abs. 3 KFG i.V.m. § 107 Abs. 3).", "So viele wie Platz haben — Feuerwehrfahrzeuge sind davon ausgenommen", "Maximal 8 Personen — mehr ist nie erlaubt", "Die Mannschaftsstärke der taktischen Einheit zählt, nicht der Zulassungsschein"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Unter welchen Voraussetzungen müssen Kinder in Feuerwehrfahrzeugen angegurtet werden?", "opts": ["Bei Fahrzeugen bis 3,5 to hzl. Gesamtgewicht muss der Lenker darauf achten, dass Kinder unter 12, die kleiner als 1,50 m sind, auch in Feuerwehrfahrzeugen angegurtet werden, sofern diese mit Sicherheitsgurten ausgerüstet sind. Ausnahmen: besondere Verkehrslage, die den Nichtgebrauch rechtfertigt, oder bei Beförderung bei Einsatzfahrten mit Blaulicht oder Folgetonhorn.", "Kinder müssen in Feuerwehrfahrzeugen niemals angegurtet werden", "Kinder unter 14 müssen immer angegurtet werden — ohne Ausnahme", "Nur bei Fahrzeugen über 3,5 to gilt die Gurtpflicht für Kinder"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Müssen sich Erwachsene im Feuerwehrfahrzeug angurten?", "opts": ["Ja, wenn der Sitzplatz mit einem Sicherheitsgurt ausgerüstet ist. Ausnahme: bei Einsatzfahrzeugen (Blaulicht oder Folgetonhorn eingeschaltet), wenn der Gebrauch des Sicherheitsgurtes mit dem Zweck der Fahrt unvereinbar ist (z. B. wenn im Fahrzeug schon Atemschutzausrüstung angelegt wird).", "Nein — in Feuerwehrfahrzeugen besteht nie Gurtpflicht", "Ja — auch während Einsatzfahrten mit Folgetonhorn gilt ausnahmslos Gurtpflicht", "Nur der Lenker muss sich angurten, die Mannschaft nicht"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Ist der Lenker dafür verantwortlich, dass sich die übrigen Insassen angurten?", "opts": ["Lenker und beförderte Personen sind je für sich zum Gebrauch des Sicherheitsgurtes verpflichtet, nur bei Kindern ist der Lenker dafür verantwortlich.", "Ja — der Lenker haftet für alle Insassen", "Nein — jeder ist selbst verantwortlich, auch die Kinder", "Nur bei Einsatzfahrten ist der Lenker verantwortlich"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Dürfen Sie mit einem Feuerwehrfahrzeug in einer 30 km/h Zone mit 50 km/h oder mit 80 km/h fahren bzw. wie schnell darf man dort fahren?", "opts": ["Bei Einsatzfahrten sind Feuerwehrfahrzeuge auf Fahrten zu Orten eines dringenden Einsatzes nicht an Geschwindigkeitsbeschränkungen gemäß StVO oder KDV gebunden. Die Fahrgeschwindigkeit ist jedoch den konkreten Verhältnissen anzupassen; auch der Grundsatz „Fahren auf Sicht“ ist zu beachten.", "Ja — bei Einsatzfahrten gilt generell keine Geschwindigkeitsbegrenzung und „Fahren auf Sicht“ ist aufgehoben", "Nein — Feuerwehrfahrzeuge müssen sich immer an die Beschilderung halten", "Nur mit Blaulicht, nicht mit Folgetonhorn, darf schneller gefahren werden"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Dürfen bei Einsatzübungsfahrten Blaulicht und Folgetonhorn verwendet werden und Geschwindigkeiten überschritten werden?", "opts": ["Ja, aber nur wenn es der Zweck der Einsatzübungsfahrt erfordert und sonst in geeigneter Weise für die Verkehrssicherheit vorgesorgt ist (z. B. Absicherung der Strecke durch Streckenposten).", "Nein — bei Übungen sind Blaulicht und Folgetonhorn strikt verboten", "Ja — bei Übungen gelten dieselben Regeln wie bei echten Einsätzen", "Ja — Blaulicht immer, Folgetonhorn nur auf Autobahnen"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Hat ein Feuerwehrfahrzeug immer Vorrang?", "opts": ["Nein, nur wenn Blaulicht oder Folgetonhorn eingeschaltet sind.", "Ja — ein Feuerwehrfahrzeug hat immer Vorrang", "Ja — wenn die Feuerwehr im Einsatz ist, auch ohne Warnzeichen", "Nein — Feuerwehrfahrzeuge haben nie Vorrang"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Wann dürfen Sie die Warnzeichen einschalten?", "opts": ["Nur bei Gefahr im Verzug, z. B. bei Fahrten zum und vom Ort der dringenden Hilfeleistung oder zum Ort des sonstigen dringenden Einsatzes. Das Blaulicht darf aus Gründen der Verkehrssicherheit auch am Ort des Einsatzes verwendet werden.", "Bei jeder Ausfahrt mit Feuerwehrfahrzeug", "Bei Übungen ist das Folgetonhorn verboten", "Nur wenn die Bezirkszentrale es genehmigt"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Ist der Lenker eines Einsatzfahrzeuges an Verkehrsverbote oder Verkehrsbeschränkungen gebunden?", "opts": ["Bei Einsatzfahrten (Blaulicht oder Folgetonhorn) ist er grundsätzlich nicht an Verkehrsverbote oder Verkehrsbeschränkungen gebunden; er darf hierbei jedoch nicht Personen gefährden oder Sachen beschädigen. Bei rotem Licht darf man nur in eine Kreuzung einfahren, wenn man vorher anhält und sich überzeugt, dass hierbei nicht Menschen gefährdet oder Sachen beschädigt werden. Einbahnstraßen dürfen in der Gegenrichtung befahren werden, aber nur, wenn der Einsatzort anders nicht oder nicht in der gebotenen Zeit erreichbar ist oder wenn Ausnahmen für andere Kraftfahrzeuge oder Fuhrwerke bestehen.", "Nein — Einsatzfahrzeuge sind von allen Verboten ausgenommen, ohne Rücksicht auf Gefährdungen", "Ja — Einsatzfahrzeuge müssen sich immer an alle Verbote halten", "Nur bei rotem Licht sind Einsatzfahrzeuge ausgenommen"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Dürfen Sie als Einsatzfahrer gegen die Einbahn fahren?", "opts": ["Nur, wenn der Einsatzort anders nicht oder nicht in der gebotenen Zeit erreichbar ist oder wenn Ausnahmen für andere Kraftfahrzeuge bestehen (§ 26 Abs. 3 StVO). — Zusatzfrage: Haben Sie dann Vorrang gegenüber entgegenkommenden Fahrzeugen? Ja. — Zusatzfrage: Wie haben sich die anderen Verkehrsteilnehmer zu verhalten? Platz machen.", "Ja — Einsatzfahrer dürfen Einbahnen immer in Gegenrichtung befahren", "Nein — auch Einsatzfahrer dürfen niemals gegen die Einbahn fahren", "Ja — aber nur wenn die Polizei die Straße sperrt"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Welche Probleme können auftauchen, wenn Sie als Einsatzfahrer unberechtigt gegen die Einbahn fahren?", "opts": ["Verwaltungsstrafverfahren · Mitverschulden bei einem Unfall", "Nur eine Verwarnung durch den Kommandanten", "Keine Probleme — Einsatzfahrer genießen Immunität", "Der Führerschein wird sofort entzogen"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "In welcher Reihenfolge haben beim Zusammentreffen von verschiedenen Einsatzfahrzeugen diese Vorrang?", "opts": ["Rettungsfahrzeuge · Fahrzeuge der Feuerwehr · Fahrzeuge des Sicherheitsdienstes · sonstige Einsatzfahrzeuge", "Fahrzeuge der Feuerwehr · Rettungsfahrzeuge · Sicherheitsdienst · sonstige", "Die Reihenfolge ergibt sich nach Ankunft — wer zuerst kommt, fährt zuerst", "Sonstige Einsatzfahrzeuge · Feuerwehr · Rettung · Sicherheitsdienst"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Wie haben sich alle Straßenbenützer einem herannahenden Einsatzfahrzeug gegenüber zu verhalten?", "opts": ["Platz machen, Vorrang geben", "Anhalten, bis das Einsatzfahrzeug vorüber ist", "Hupen und warnen", "Normal weiterfahren"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Müssen Sie als Einsatzfahrer bei einer Kreuzung mit Rotlicht anhalten?", "opts": ["Ja, nur nach dem Anhalten und Überzeugen, dass niemand gefährdet wird, darf Rotlicht überfahren werden.", "Nein — Einsatzfahrer dürfen ohne Anhalten über Rot fahren", "Nur bei Fußgängerampeln muss angehalten werden", "Ja — aber nur in der Nacht"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Oberlöschmeister Meier fährt mit Blaulicht zur Pizzeria, weil seine Pizza kalt wird. Hat er gegenüber anderen Verkehrsteilnehmern Vorrang?", "opts": ["Ja, die Vorrangregelung knüpft nicht daran an, ob jemand zu Recht oder zu Unrecht Blaulicht oder Folgetonhorn eingeschaltet hat. — Zusatzfrage: Hat Oberlöschmeister Meier irgendwelche Konsequenzen zu befürchten? Ja, ein Verwaltungsstrafverfahren wegen Verstoßes gegen § 26 Abs. 1 KFG i.V.m. § 134 KFG; Mitverschulden im Falle eines Unfalls.", "Nein — der Vorrang gilt nur bei berechtigter Verwendung der Warnzeichen", "Nein — und Konsequenzen gibt es auch keine, solange nichts passiert", "Ja — aber nur gegenüber Fußgängern"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Hat der Einsatzfahrer auch Vorrang bei einer ampelgeregelten Kreuzung bei Rotlicht?", "opts": ["Nein, in diesem Fall muss er anhalten und sich überzeugen, dass er niemanden gefährdet.", "Ja — bei eingeschaltetem Blaulicht gilt Vorrang auch bei Rot", "Ja — wenn er die Sirene eingeschaltet hat", "Ja — aber nur wenn keine anderen Fahrzeuge unterwegs sind"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Wer ist schuld, wenn Sie als Einsatzfahrer bei Rot in die Kreuzung einfahren und es kommt zu einem Unfall?", "opts": ["Der Einsatzfahrer; unter Umständen trifft den anderen ein Mitverschulden, wenn er zu spät gebremst hat oder zu schnell gefahren ist.", "Immer der andere — er hätte Platz machen müssen", "Die Feuerwehr als Organisation haftet, nicht der Lenker", "Niemand — bei Einsatzfahrten gilt keine Schuldfrage"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Welche Dokumente haben Sie beim Lenken eines Feuerwehrfahrzeuges der Klasse C mitzuführen?", "opts": ["Den Feuerwehrführerschein und den Führerschein; beides ist auf Verlangen der Exekutive zur Überprüfung auszuhändigen (§ 14 Abs. 1 FSG).", "Nur den zivilen Führerschein", "Nur den Feuerwehrführerschein", "Führerschein, Feuerwehrpass und Dienstausweis"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Welche Alkoholbestimmungen gibt es für Feuerwehrfahrzeuge?", "opts": ["Bis 7,5 t höchstzulässige Gesamtmasse: 0,5 ‰; über 7,5 t höchstzulässige Gesamtmasse: mit Feuerwehrführerschein 0,5 ‰; ohne Feuerwehrführerschein 0,1 ‰ (§ 32a Abs. 6 FSG).", "Für Feuerwehrfahrzeuge gilt generell 0,0 ‰", "Für Feuerwehrfahrzeuge gilt generell 0,5 ‰, unabhängig vom Gewicht", "Bei Einsatzfahrten gelten keine Alkoholgrenzen"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Dürfen Sie mit einem Feuerwehrführerschein mehr als 8 Personen im Feuerwehrfahrzeug mitführen, obwohl Sie keinen Busführerschein (Lenkberechtigung der Klasse D) besitzen?", "opts": ["Ja", "Nein", "Nur bei Einsatzfahrten", "Nur mit Zustimmung des Kommandanten"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Unter welchen Voraussetzungen dürfen mehr als 8 Personen in einem Feuerwehrfahrzeug befördert werden?", "opts": ["Das Fahrzeug muss dafür laut Zulassungsschein geeignet sein, der Lenker muss entweder eine zivile Lenkberechtigung der Klasse D oder eine zivile Lenkberechtigung der Klasse B und zusätzlich einen Feuerwehrführerschein aufweisen (§ 1 Abs. 3 FSG).", "Wenn der Kommandant die Erlaubnis gibt", "Wenn genügend Sitzplätze und Gurte vorhanden sind", "Bei Einsatzfahrten immer"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Dürfen Sie mit einer zivilen Lenkberechtigung B und einem Feuerwehrführerschein einen zivilen LKW lenken?", "opts": ["Nein", "Ja", "Ja — bis 7,5 t", "Ja — wenn die Feuerwehr zustimmt"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Dürfen Sie mit einem Feuerwehrfahrzeug ohne Vignette oder Go-Box eine mautpflichtige Autobahn befahren?", "opts": ["Ja (Feuerwehrfahrzeuge, an denen Blaulicht angebracht ist, sind gemäß § 5 Abs. 1 Bundesstraßen-Mautgesetz 2002 von der Maupflicht ausgenommen).", "Nein — auch Feuerwehrfahrzeuge brauchen eine Vignette", "Ja — aber nur auf der Anfahrt zum Einsatz", "Nur mit einer Sondergenehmigung des Landes"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Wie bzw. mit welchen Abständen sind Einsatzstellen abzusichern?", "opts": ["Abhängig von der Witterung und den Straßenverhältnissen, im Ortsgebiet jedoch mindestens 50 m, auf Freilandstraßen 150 m bis 250 m und auf Autobahnen 250 m bis 400 m.", "Einheitlich 100 m überall", "Im Ortsgebiet 20 m, auf Freilandstraßen 50 m, auf Autobahnen 100 m", "Der Abstand ist nicht geregelt"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "Rechtliches", "src": "Rechtliches", "f": "Was passiert mit Ihrem Feuerwehrführerschein, wenn Ihnen die zivile Lenkberechtigung entzogen wird?", "opts": ["Wird für die Dauer der Entziehung ungültig (§ 32a Abs. 4 FSG).", "Er bleibt weiterhin gültig", "Er wird eingezogen und vernichtet", "Er muss neu gemacht werden — er läuft ab"], "r": 0, "e": "", "m2": "Rechtliches"}, {"m": "5,5t-Lenkberechtigung", "src": "DO Allgemeine Informationen 5,5t v02 · Dienstanweisung § 1", "f": "Mit welcher Lenkberechtigung dürfen Feuerwehrfahrzeuge bis 5.500 kg höchstzulässige Gesamtmasse (HzG) gelenkt werden?", "opts": ["Mit der zivilen Lenkberechtigung Klasse B, sofern zusätzlich die Bestätigung „Lenken von Feuerwehrfahrzeugen bis 5.500 kg HzG“ (§ 1 Abs. 3 FSG) vorliegt.", "Mit jeder Lenkberechtigung ab Klasse B ohne Zusatz", "Nur mit dem Feuerwehrführerschein (Klasse C)", "Nur mit Lenkberechtigung C1"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "DO Allgemeine Informationen 5,5t v02 · Dienstanweisung § 1"}, {"m": "5,5t-Lenkberechtigung", "src": "DO Allgemeine Informationen 5,5t v02", "f": "Wo finden Ausbildung und Prüfung für die 5,5t-Berechtigung statt?", "opts": ["In der Feuerwehr — Ausbildung durch bestellte Ausbilder, Prüfung durch bestellte Prüfer (beide von der Landes-Feuerwehrschule bestellt).", "In der Fahrschule — wie beim zivilen Führerschein", "An der Landes-Feuerwehrschule in Linz", "Beim Bezirksfeuerwehrkommando"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "DO Allgemeine Informationen 5,5t v02"}, {"m": "5,5t-Lenkberechtigung", "src": "Vortrag 5,5t Infos · Folie 3", "f": "Welche Reihenfolge ist korrekt, um die 5,5t-Bestätigung zu erhalten?", "opts": ["1. Feuerwehrkommandant legt Auszubildende fest → 2. bestellte Ausbilder führen die Ausbildung durch → 3. bestellte Prüfer nehmen die Prüfung ab → 4. Feuerwehrkommandant stellt Antrag an den Oö. LFV → 5. LFV prüft und stellt die Bestätigung aus → 6. Bestätigung wird an die Feuerwehr übermittelt.", "1. LFV-Ausbildung in Linz → 2. Prüfung an der LFS → 3. Ausstellung", "1. Antrag an die BH → 2. Prüfung durch die Exekutive → 3. Eintrag im Führerschein", "1. Fahrschule → 2. Prüfung → 3. Bestätigung durch das Verkehrsministerium"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "Vortrag 5,5t Infos · Folie 3"}, {"m": "5,5t-Lenkberechtigung", "src": "Dienstanweisung 5,5t § 2", "f": "Welche Voraussetzungen muss der Antragsteller für die 5,5t-Berechtigung erfüllen?", "opts": ["Mitglied/Bediensteter einer Feuerwehr sein · nicht mehr in der Führerschein-Probezeit sein · erfolgreiche feuerwehrinterne Ausbildung · während der Ausbildung max. 0,1 Promille (0,1 g/l Blut bzw. 0,05 mg/l Atemluft).", "Mindestalter 21 Jahre · Besitz der Klasse B seit 2 Jahren", "Besitz der Klassen B und C1 · ärztliche Untersuchung", "Absolvierter Truppmann-Lehrgang · Mindestalter 16 Jahre"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "Dienstanweisung 5,5t § 2"}, {"m": "5,5t-Lenkberechtigung", "src": "Dienstanweisung 5,5t § 1", "f": "Wann wird die Bestätigung zum Lenken von Feuerwehrfahrzeugen bis 5.500 kg HzG NICHT ausgestellt bzw. ungültig?", "opts": ["Wenn der Antragsteller im Besitz der Klasse C1 oder C ist — die Bestätigung setzt voraus, dass NUR die Klasse B vorliegt.", "Wenn der Antragsteller jünger als 25 Jahre ist", "Wenn die Feuerwehr mehr als 50 Mitglieder hat", "Wenn das Fahrzeug einen Anhänger ziehen darf"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "Dienstanweisung 5,5t § 1"}, {"m": "5,5t-Lenkberechtigung", "src": "Dienstanweisung 5,5t § 1 + § 9", "f": "Was gilt, wenn eine der Voraussetzungen für die 5,5t-Berechtigung wegfällt (z. B. Probezeit-Verstoß, Austritt aus der Feuerwehr)?", "opts": ["Sämtliche Berechtigungen und Bestätigungen verlieren ihre Gültigkeit — bei Austritt aus der Feuerwehr zieht der Feuerwehrkommandant die Bestätigung ein und übermittelt sie dem LFV.", "Die Bestätigung bleibt lebenslang gültig", "Die Bestätigung kann einfach weiterverwendet werden, solange sie nicht abgelaufen ist", "Nur die Feuerwehr muss informiert werden, sonst nichts"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "Dienstanweisung 5,5t § 1 + § 9"}, {"m": "5,5t-Lenkberechtigung", "src": "Dienstanweisung 5,5t § 7", "f": "Wie ist die 5,5t-Bestätigung ausgestaltet und was ist bei Fahrten zu beachten?", "opts": ["Scheckkarte in der Farbe Gelb — nur in Verbindung mit einer aufrechten Lenkberechtigung Klasse B gültig · bei Fahrten mitzuführen · auf Verlangen der zuständigen Organe auszuhändigen.", "Grüner Aufkleber für die Windschutzscheibe — muss sichtbar angebracht sein", "Rosa Scheckkarte — gilt ohne Führerschein", "Blaues Kartendokument — nur im Feuerwehrhaus zu hinterlegen"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "Dienstanweisung 5,5t § 7"}, {"m": "5,5t-Lenkberechtigung", "src": "Dienstanweisung 5,5t § 1", "f": "Darf die Bestätigung der Rettungsorganisation zum Lenken von Feuerwehrfahrzeugen verwendet werden — und umgekehrt?", "opts": ["Nein, eine wechselseitige Verwendung ist nicht zulässig. (Anerkennung der Ausbildung bei einer anderen Organisation gemäß § 7 FSG-FRV ist aber möglich.)", "Ja, die Bestätigungen sind österreichweit austauschbar", "Ja, aber nur innerhalb desselben Bezirks", "Nein, und es gibt auch keine Anerkennung der Ausbildung"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "Dienstanweisung 5,5t § 1"}, {"m": "5,5t-Lenkberechtigung", "src": "FSG-FRV § 5 Abs. 1 (BGBl. II Nr. 79/2011) · Dienstanweisung § 3", "f": "Welchen Umfang und welche Inhalte hat die theoretische Ausbildung zur 5,5t-Berechtigung?", "opts": ["Mind. 3 Unterrichtseinheiten (UE = 50 Minuten): spezielles Straßenverkehrsrecht für Lenker von Einsatzfahrzeugen · Fahrzeugtechnik (Fehlererkennung, Fehlerbehebung, einfache Wartung) · Fahrphysik · Gefahrenlehre und Partnerkunde.", "Mind. 12 Unterrichtseinheiten: nur StVO und KFG", "Mind. 5 Unterrichtseinheiten: nur Fahrpraktikas", "Mind. 2 Unterrichtseinheiten: Fahrzeugkunde und Funk"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "FSG-FRV § 5 Abs. 1 (BGBl. II Nr. 79/2011) · Dienstanweisung § 3"}, {"m": "5,5t-Lenkberechtigung", "src": "FSG-FRV § 5 Abs. 2 (BGBl. II Nr. 79/2011) · Dienstanweisung § 3", "f": "Welchen Umfang und welche Inhalte hat die praktische Ausbildung zur 5,5t-Berechtigung?", "opts": ["Mind. 5 Unterrichtseinheiten: Einschulung auf die Fahrzeuge, die gelenkt werden sollen · Zustandsüberprüfung des Fahrzeuges · Fahrübungen zum Kennenlernen des Fahrzeuges. Übungsfahrten auf Straßen mit öffentlichem Verkehr sind möglich und schriftlich zu dokumentieren.", "Mind. 10 Fahrlektionen à 45 Minuten mit Feuerwehrfahrzeug über 7,5 t", "Mind. 2 Fahrlektionen in der Fahrschule", "Nur eine Probefahrt mit dem Kommandanten"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "FSG-FRV § 5 Abs. 2 (BGBl. II Nr. 79/2011) · Dienstanweisung § 3"}, {"m": "5,5t-Lenkberechtigung", "src": "Dienstanweisung 5,5t § 4 · FSG-FRV § 6 Abs. 1", "f": "Wie ist die theoretische Prüfung zur 5,5t-Berechtigung aufgebaut und wann ist sie positiv?", "opts": ["20 Fragen anhand des Fragenkataloges/Fragebogens (mündlich, schriftlich oder computerunterstützt möglich) — von 20 Fragen müssen mindestens 16 richtig beantwortet werden.", "35 Fragen, mindestens 27 richtig", "10 Fragen, alle richtig", "Mündliches Prüfungsgespräch mit 4 Themen ohne Fragenkatalog"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "Dienstanweisung 5,5t § 4 · FSG-FRV § 6 Abs. 1"}, {"m": "5,5t-Lenkberechtigung", "src": "Dienstanweisung 5,5t § 4 · FSG-FRV § 6 Abs. 2", "f": "Welche Teile umfasst die praktische Prüfung zur 5,5t-Berechtigung?", "opts": ["Überprüfungen am Fahrzeug (insbesondere bei Dienst-/Fahrtantritt) · Langsamfahrübungen (Einparken, Umkehren, Rückwärtsfahren) im beruhigten Verkehrsraum/Gelände · Prüfungsfahrt auf Straßen im öffentlichen Verkehr von mind. 25 Minuten · Besprechung erlebter Situationen, wenn erforderlich. Keine groben StVO-Verstöße während der Prüfungsfahrt.", "Nur eine Prüfungsfahrt von 45 Minuten über 7,5 t", "Nur Langsamfahrübungen auf dem Rastplatz", "Prüfungsfahrt von 10 Minuten um das Feuerwehrhaus"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "Dienstanweisung 5,5t § 4 · FSG-FRV § 6 Abs. 2"}, {"m": "5,5t-Lenkberechtigung", "src": "Dienstanweisung 5,5t § 3 · Nachweis Ausbildung", "f": "Mit welchen Tafeln ist das Fahrzeug während Ausbildung, Übungsfahrten und Prüfung zu kennzeichnen?", "opts": ["Mit den Tafeln „L“ (weiße Schrift auf hellblauem Grund) aus beiden Fahrtrichtungen sichtbar — § 120 Abs. 2 KFG. Der Ausbilder/Prüfer muss die Bestellungsurkunde mitführen (§ 120 Abs. 3 KFG).", "Mit dem Feuerwehrwappen und der Bezeichnung „Ausbildungsfahrt“", "Mit orangen Warntafeln wie bei Gefahrguttransporten", "Gar nicht — Dienstfahrten brauchen keine Kennzeichnung"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "Dienstanweisung 5,5t § 3 · Nachweis Ausbildung"}, {"m": "5,5t-Lenkberechtigung", "src": "Dienstanweisung 5,5t § 6 · DO Allgemeine Informationen v02", "f": "Was gilt für Ausbilder UND Prüfer der 5,5t-Berechtigung? (Anforderungen laut Dienstanweisung)", "opts": ["Mind. 7 Jahre im Besitz der Lenkberechtigung B · Ausbildung C1 ODER Feuerwehrführerschein erfolgreich absolviert · nüchtern (max. 0,1 ‰) · auf Übungsfahrten neben dem Fahrschüler sitzen (außer Einparken/Rückwärtsfahren) · für Verkehrsvorschriften-Genauigkeit des Fahrschülers sorgen · Prüfer: keine schwere Verkehrsdelikte in den letzten 3 Jahren. Ausbilder und Prüfer dürfen NICHT dieselbe Person sein.", "Mind. 5 Jahre Klasse B · Truppführer-Lehrgang · Feuerwehrarzt-Zeugnis", "Ausbilder und Prüfer können dieselbe Person sein, das spart Personal", "Jedes Mitglied mit Klasse B und 3 Jahren Dienstzeit kann ausbilden und prüfen"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "Dienstanweisung 5,5t § 6 · DO Allgemeine Informationen v02"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 5–6 (§ 57 KFG)", "f": "Was besagt die Überprüfungspflicht von Kraftfahrzeugen und Anhängern vor Fahrantritt (§ 57 KFG)?", "opts": ["Der Lenker darf ein Fahrzeug erst in Betrieb nehmen, wenn er sich soweit zumutbar überzeugt hat, dass das Fahrzeug, ein mitgeführter Anhänger und deren Beladung den Vorschriften entsprechen — Verkehrs- und Betriebssicherheit, Bau-, Verwendungs- und Verhaltensvorschriften. Bei der Feuerwehr: Kontrolle vor Fahrantritt und nach jeder Inbetriebnahme, mindestens jedoch 1 x monatlich.", "Die Überprüfung macht ausschließlich der Gerätewart, der Lenker braucht nichts kontrollieren", "Einmal jährlich bei der Begutachtung genügt", "Die Kontrolle ist nur nach Unfällen vorgeschrieben"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 5–6 (§ 57 KFG)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 6", "f": "Welche Punkte umfasst die Verkehrssicherheits-Kontrolle vor Fahrantritt (Sicht- und Funktionskontrolle)?", "opts": ["Bremsen (Stand- und Rollbremsprobe) · Lenkung (spielfrei, leichtgängig) · Bereifung (Profiltiefe, Zustand, Luftdruck) · Rückspiegel (Innen- und Außenspiegel einstellen) · Scheiben und Waschanlage · Beleuchtung, Hupe, Signalanlage · Defrosteranlage · Kennzeichen, Sauberkeit, Zustand.", "Nur Ölstand und Kraftstoff", "Nur Reifen und Bremsen", "Nur Scheinwerfer und Hupe"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 6"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 7–13 (WOLKE-Check)", "f": "WOFÜR steht die Merkhilfe „WOLKE“ bei der Betriebssicherheits-Kontrolle?", "opts": ["W = Wasser (Kühlwasser mit Frostschutz −30 °C, Scheibenwaschanlage, Wischerblätter, Löschwassertank, Pumpen und Leitungen) · O = Öl (Motor-, Getriebeöl, Bremsflüssigkeit — Wechsel spätestens nach 2 Jahren) · L = Luft (Reifendruck auch am Reserverad, Profiltiefe, Zustand) · K = Kraftstoff (voll tanken, richtigen Kraftstoff, Winterdiesel, Kanisterfarben) · E = Elektrik (alle Verbraucher, Scheinwerfereinstellung, Keilriemen) — dazu die Auspuffanlage.", "W = Warnblinker, O = Öldruck, L = Lautsprecher, K = Klimaanlage, E = Eiskratzer", "W = Wagenheber, O = Ölwechsel-Termine, L = Licht, K = Kennzeichen, E = Ersatzrad", "Es steht für die fünf Hersteller der Fahrzeugkomponenten"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 7–13 (WOLKE-Check)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 8 (WOLKE – Wasser)", "f": "WOLKE „W“ — Wasser: was ist bei der Feuerwehr alles zu kontrollieren?", "opts": ["Kühlwasser mit Frostschutz (− 30 °C) · Scheibenwaschanlage mit Scheibenreiniger · Wischerblätter und Spritzdüsen · Löschwassertank (kein abgestandenes Wasser, Tankheizung) · Pumpen und Leitungen.", "Nur der Kühlwasserstand — der Rest gehört zum Gerätewart", "Trinkwasserflaschen für die Mannschaft", "Nur die Waschanlage im Feuerwehrhaus"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 8 (WOLKE – Wasser)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 9 (WOLKE – Öl)", "f": "WOLKE „O“ — Öl: welche Kontrollen und Intervalle gelten?", "opts": ["Motor- und Getriebeölstand prüfen (Wechsel/Intervall laut Betriebsanleitung) · Bremsflüssigkeit von der Werkstätte prüfen lassen — Wechsel spätestens nach 2 Jahren.", "Ölstand nur bei der Jahreswartung prüfen · Bremsflüssigkeit ist wartungsfrei", "Motoröl wechselt der Lenker selbst alle 5.000 km", "Getriebeöl gibt es bei modernen Fahrzeugen nicht"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 9 (WOLKE – Öl)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 10–11 (WOLKE – Luft, Profiltiefen)", "f": "WOLKE „L“ — Luft: welche Profiltiefen gelten für das Feuerwehrfahrzeug?", "opts": ["LKW: mind. 2,0 mm · PKW: mind. 1,6 mm · Winter- und Ganzjahresreifen: mind. 5,0 mm — dazu Zustand der Reifen (Beschädigungen, Alter) und Luftdruck laut Betriebsanleitung (auch Reserverad, Beschriftung am Kotflügel beachten).", "Mind. 1,6 mm bei allen Reifen", "Mind. 8 mm bei Feuerwehrfahrzeugen", "Profiltiefe spielt bei Geländefahrzeugen keine Rolle"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 10–11 (WOLKE – Luft, Profiltiefen)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 12 (WOLKE – Kraftstoff)", "f": "WOLKE „K“ — Kraftstoff: was ist zu beachten?", "opts": ["Fahrzeug, Aggregate und Reservekanister immer voll tanken · regelmäßig Übungsfahrten · Probelauf der Feuerlöschpumpe (unter Belastung, auf Trockenlauf achten) · richtigen Kraftstoff verwenden · begrenzte Haltbarkeit · rechtzeitig auf Winterdiesel umstellen (auch bei den Kanistern!). Kanisterfarben: Benzin = rot · Gemisch (Benzin + Öl) = rot mit blauen Streifen · Diesel = gelb.", "Kraftstoff nachfüllen, wenn der Tank leer ist — Haltbarkeit ist unbegrenzt", "Winterdiesel braucht es in Österreich nicht", "Alle Kanister sind rot, Farbe sagt nichts aus"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 12 (WOLKE – Kraftstoff)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 13 (WOLKE – Elektrik)", "f": "WOLKE „E“ — Elektrik: was wird kontrolliert?", "opts": ["Kontrolle sämtlicher elektrischer Verbraucher · Scheinwerfereinstellung kontrollieren · Keilriemen auf Risse, Brüche und Spannung prüfen.", "Nur die Batteriespannung messen", "Nur das Blaulicht testen", "Elektrik kontrolliert ausschließlich die Werkstätte"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 13 (WOLKE – Elektrik)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 14–15 (Beladung, Dokumente)", "f": "Was ist bei der Kontrolle der Beladung und Dokumente vor Fahrantritt zu prüfen?", "opts": ["Ladungssicherung im Fahrer- und Mannschaftsraum sowie am Fahrzeug · Massen und Abmessungen (HzG, HzG der Fahrzeugkombination mit Anhänger, Achslasten, tatsächliche Länge/Breite/Höhe) · vorgeschriebene Ausrüstung laut KFG (Verbandszeug, Pannendreieck ECE, reflektierende Warnwesten, Unterlegkeile) · Aufschriften (Massen- und Fahrzeugkennschild) · Dokumente im Fahrzeug (Zulassungsschein, Fahrtenbuch) · Dokumente gemäß FSG (Führerschein, Bestätigung zum Lenken von Feuerwehrfahrzeugen bis 5.500 kg HzG).", "Nur die Bestätigung 5,5t mitnehmen, der Rest ist freiwillig", "Beladung muss nicht gesichert werden, solange alles im Fahrzeug eingebaut ist", "Fahrtenbuch wird nur bei Einsätzen geführt"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 14–15 (Beladung, Dokumente)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 16 (Einsatzbereitschaft)", "f": "Was gilt, wenn Mängel am Fahrzeug oder an der Pumpe festgestellt werden, die Verkehrs-/Betriebssicherheit betreffen?", "opts": ["Nicht sofort behebbare Fehler unverzüglich dem Gerätewart oder Kommandanten melden — bei Fehlern, die die Verkehrs- und Betriebssicherheit betreffen, ist das Fahrzeug AUSSER Betrieb zu nehmen. Auf Vollständigkeit der Fahrzeugbestückung achten.", "Mit dem Mangel weiterfahren — die nächste Werkstatt sieht danach", "Den Mangel nur ins Fahrtenbuch eintragen und weiterfahren", "Selbst reparieren, egal welche Qualifikation"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 16 (Einsatzbereitschaft)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 17 (Übungsfahrten, Kontrollen)", "f": "Was ist zu Übungsfahrten, Kontrollen und dem Fahrtenbuch bei Feuerwehrfahrzeugen vorgeschrieben?", "opts": ["Kontrollen mit Checklisten durchführen · regelmäßige Übungsfahrten (mind. 10 km) · Fahrtenbuch grundsätzlich nach JEDER Fahrt ausfüllen · Einsatzgebiet erkunden.", "Übungsfahrten einmal jährlich, Fahrtenbuch nur bei Einsätzen", "Checklisten sind nicht vorgesehen", "Das Einsatzgebiet erkundet die Bezirksalarmzentrale"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 17 (Übungsfahrten, Kontrollen)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 20 (StVO)", "f": "Wann gilt ein Feuerwehrfahrzeug als „Einsatzfahrzeug“ und wann dürfen Blaulicht und Folgetonhorn verwendet werden?", "opts": ["Einsatzfahrzeug = für die Dauer der Verwendung von Blaulicht ODER Folgetonhorn. Beide Signale nur bei Gefahr in Verzug — für Fahrten zum und vom Ort der dringenden Hilfeleistung oder zum Ort des sonstigen dringenden Einsatzes. Die missbräuchliche Verwendung ist strafbar!", "Ein Feuerwehrfahrzeug ist IMMER Einsatzfahrzeug, auch ohne eingeschaltete Signale", "Blaulicht darf zu jeder Übungsfahrt eingeschaltet werden", "Folgetonhorn darf auch im Feuerwehrhaus zum Warmlaufen verwendet werden"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 20 (StVO)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 22–23, 27 (StVO-Sonderrechte)", "f": "Welche Sonderrechte haben Lenker von Einsatzfahrzeugen — und wo gelten KEINE Sonderrechte?", "opts": ["Nicht gebunden an Verkehrsverbote und -beschränkungen (Geschwindigkeit den Verhältnissen anpassen!) · bei rotem Licht einfahren, aber vorher anhalten, niemanden gefährden · Einbahn/Richtungsfahrbahn gegen die Fahrtrichtung nur, wenn der Einsatzort anders nicht oder nicht in der gebotenen Zeit erreichbar ist · Fußgängerzonen und Bus-/Taxispuren dürfen befahren werden. KEINE Sonderrechte: Eisenbahnkreuzungen · Höhen- und Gewichtsbeschränkungen (Ortskenntnis).", "Vollständiger Freibrief: alle Regeln dürfen ignoriert werden", "Eisenbahnkreuzungen dürfen bei Blaulicht ohne Anhalten überquert werden", "Höhenbeschränkungen gelten für Einsatzfahrzeuge nicht"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 22–23, 27 (StVO-Sonderrechte)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 24 (Vorrang)", "f": "Wie lautet die Vorrang-Reihenfolge beim Zusammentreffen verschiedener Einsatzfahrzeuge?", "opts": ["1. Rettung (Leben) → 2. Feuerwehr (Sachen) → 3. Polizei/Sicherheitsdienst → 4. sonstige Einsatzfahrzeuge (z. B. Notdienste, Militärstreife).", "1. Feuerwehr → 2. Rettung → 3. Polizei → 4. sonstige", "1. Polizei → 2. Feuerwehr → 3. Rettung → 4. sonstige", "Wer zuerst Blaulicht eingeschaltet hat, hat Vorrang"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 24 (Vorrang)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 25 (Vertrauensgrundsatz)", "f": "Was besagt der Vertrauensgrundsatz — und gegenüber wem gilt er NICHT?", "opts": ["Man darf darauf vertrauen, dass andere die maßgeblichen Rechtsvorschriften befolgen. AUSNAHMEN: Kinder · Seh- oder Hörbehinderte (weißer Stock / gelbe Armbinde) · Menschen mit Beeinträchtigung/Gebrechliche · auffällige Personen. Gegenüber diesen: Fahrgeschwindigkeit vermindern und bremsbereit sein!", "Der Vertrauensgrundsatz gilt gegenüber allen Verkehrsteilnehmern ausnahmslos", "Der Vertrauensgrundsatz gilt nur innerhalb des Ortsgebietes", "Gegen Kinder darf man besonders schnell vertrauen, weil sie gelernte Programme haben"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 25 (Vertrauensgrundsatz)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 26 (KFG/StVO-Sonderregelungen)", "f": "Welche Sonderregelungen gelten für Feuerwehrfahrzeuge bei Sicherheitsgurt, Fahrtenschreiber, Vignette und Go-Box?", "opts": ["Ausnahme von der Sicherheitsgurtpflicht bei der Einsatzfahrt (wenn der Zweck der Fahrt es erfordert) · kein Fahrtenschreiber/Wegstreckenmesser · keine Vignettenpflicht · keine Go-Box.", "Keine — Feuerwehrfahrzeuge sind hier wie alle LKW zu behandeln", "Sicherheitsgurt muss immer angelegt bleiben, auch beim Ausrüsten im Fahrzeug", "Go-Box-Pflicht gilt für Einsatzfahrten, nur Übungsfahrten sind befreit"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 26 (KFG/StVO-Sonderregelungen)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 31 (Geschwindigkeiten)", "f": "Welche Höchstgeschwindigkeiten gelten für den Feuerwehrtransporter bis 5,5 t (Nichteinsatzfall) und wovon ist die Fahrgeschwindigkeit abhängig?", "opts": ["Ortsgebiet: 50 km/h · Freilandstraße bzw. Autostraße: 70 km/h · Autobahn: 80 km/h. Nur unter günstigsten Voraussetzungen — abhängig von Straßen- und Sichtverhältnissen, Fahrbahnbeschaffenheit, Verkehrsverhältnissen, Eigenschaften von Fahrzeug und Ladung (Tank!), Können und Verfassung des Fahrers.", "Wie LKW: 50/80/100 km/h überall", "Wie PKW: 50/100/130 km/h", "Bei Einsatzfahrten gibt es ohnehin keine Geschwindigkeitsbegrenzung"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 31 (Geschwindigkeiten)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 30 (Vorschriften 5,5t)", "f": "Vorschriften 5,5 t — was gilt für LKW über 3,5 to HzG (also auch für das 5,5t-Fahrzeug)?", "opts": ["Massebegrenzung 5.500 kg HzG · mind. 1 Unterlegkeil mitführen · kein Abstellen auf Gehsteigen trotz Markierung · Aufschriften auf der rechten Seite: Eigenmasse, höchste zulässige Gesamtmasse, höchste zulässige Achslasten, Fahrzeuglänge.", "Kein Unterlegkeil nötig, das Pannendreieck genügt", "Aufschriften gehören auf die linke Fahrzeugseite", "Auf Gehsteigen darf mit Feuerwehrfahrzeug immer geparkt werden"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 30 (Vorschriften 5,5t)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 32 (Fahrverbote)", "f": "Wie sind die Fahrverbots-Zusatztafeln „Verbot für LKW über … to“ zu lesen — tatsächliche oder höchstzulässige Gesamtmasse?", "opts": ["„Fahrverbot für Fahrzeuge über … to Gesamtmasse“ = TATSÄCHLICHE Gesamtmasse (Fahrzeug und Anhänger getrennt betrachten) · „Fahrverbot für LKW über … to“ = HÖCHSTZULÄSSIGE Gesamtmasse (Anhänger und Fahrzeug getrennt betrachten).", "Beide Tafeln meinen immer die höchstzulässige Gesamtmasse", "Beide Tafeln meinen immer die tatsächliche Gesamtmasse", "Für Feuerwehrfahrzeuge gelten solche Tafeln nie"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 32 (Fahrverbote)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 33 (Überholverbot)", "f": "Dürfen Sie mit Ihrem 5,5t-Fahrzeug (LKW über 3,5 to HzG) mehrspurige Kraftfahrzeuge überholen?", "opts": ["Nein — das Überholen von mehrspurigen Kraftfahrzeugen ist für LKW mit einer HzG über 3,5 to verboten.", "Ja, mit Blaulicht immer", "Ja, wenn die Sichtweite 800 m beträgt", "Ja, auf Autobahnen ausdrücklich erlaubt"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 33 (Überholverbot)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 21 (Wochenendfahrverbot)", "f": "Vom Wochenend-Fahrverbot (Samstags- und Feiertagsfahrverbot) für LKW sind welche Fahrzeuge ausgenommen?", "opts": ["Einsatzfahrzeuge · Fahrzeuge der Feuerwehr, die typisiert sind als Spezialkraftwagen, Sonderfahrzeug oder Feuerwehrfahrzeug.", "Alle Feuerwehrfahrzeuge auch bei reinen Dienstfahrten ohne Einsatz", "Keine Feuerwehrfahrzeuge — es gelten die gleichen Zeiten wie für LKW", "Nur Fahrzeuge mit Go-Box"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 21 (Wochenendfahrverbot)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 35 (Fahrphysik)", "f": "Welche Kräfte wirken beim Fahren auf ein Fahrzeug und wie werden sie übertragen?", "opts": ["Antriebskraft · Bremskraft · Seitenführungskraft — Übertragung durch Reibung zwischen Reifen und Fahrbahn (Bodenhaftung).", "Hubkraft · Zugkraft · Schwerkraft — Übertragung über die Achsen", "Nur die Bremskraft, Antrieb und Seitenführung sind keine Kräfte", "Die Kräfte werden über die Federn übertragen"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 35 (Fahrphysik)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 36 (Schleudern)", "f": "Das Fahrzeug BRICHT HECK AUS und schleudert — wie ist das counter-Verhalten?", "opts": ["Sofort die das Schleudern verursachende Tätigkeit unterbrechen bzw. unterlassen · in Schleuderrichtung lenken · auskuppeln · nicht bremsen, solange das Fahrzeugheck Schleuderbewegungen macht.", "Voll in die Gegenrichtung lenken und Vollbremsung machen", "Handbremse ziehen, um das Heck zu stoppen", "Gas geben, um das Heck wieder zu stabilisieren"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 36 (Schleudern)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 37 (Schieben)", "f": "Das Fahrzeug schiebt über die VORDERACHSE (Schieben/Untersteuern) — richtiges Verhalten?", "opts": ["Sofort die das Schieben verursachende Tätigkeit unterbrechen · Lenkradeinschlag zurücknehmen · auskuppeln · Bremse lösen — generell: nur so viel lenken, dass kein Schieben des Fahrzeugs entsteht.", "Mehr Lenkeinschlag geben und weiter bremsen", "Handbremse anziehen, um das Heck ausbrechen zu lassen", "Vollgas geben und geradeaus halten"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 37 (Schieben)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 38 (Aquaplaning)", "f": "Wovon ist Aquaplaning abhängig und wie verhält man sich richtig?", "opts": ["Abhängig von Fahrgeschwindigkeit, Wasser- und Profiltiefe. Bei Auftreten: sofort auskuppeln · Lenkrad in Geradeausstellung festhalten · NICHT bremsen · warten, bis die Räder wieder Fahrbahnkontakt haben — falls erforderlich, danach Lenkkorrektur vornehmen.", "Aquaplaning hängt nur von der Reifenmarke ab", "Bei Aquaplaning sofort eine Vollbremsung machen", "Gegenlenken und stark beschleunigen"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 38 (Aquaplaning)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 40–41 (Gefahrenlehre, Partnerkunde)", "f": "Welche besonderen Gefahren und Gefahrenstellen kennt die Gefahrenlehre für Einsatzfahrten?", "opts": ["Unterschiedliche Fahrbahnbeschaffenheit (Asphalt, Schotter, freies Gelände) · Jahreszeiten (Eis, Schnee) · wechselnde Witterungs- und Sichtverhältnisse (Tag, Nacht, Nebel, Regen) · besondere Gefahrenstellen (Ausfahrten, Brücken, Kreuzungen) · gefährliche Partner: Kinder, unaufmerksame/überforderte Verkehrsteilnehmer · gefährliche Situationen: starker Seitenwind, riskante Überholmanöver, Unfälle, Aufregung/Stress bei der Einsatzfahrt, Nachteinsatz (Schlafunterbrechung), Einsatzstichwort.", "Nur Alkohol am Steuer ist eine Gefahr", "Nur das Wetter im Winter", "Gefahren gibt es nur auf Freilandstraßen"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 40–41 (Gefahrenlehre, Partnerkunde)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 42 (Aufgaben Anfahrt)", "f": "Was sind die Aufgaben des Fahrers bei der Anfahrt zum Einsatz?", "opts": ["Regelmäßige Übungsfahrten für den Ernstfall · eigene Fahrtauglichkeit überprüfen · nie überstürzt handeln, Ruhe bewahren · nur nach Absprache mit dem Fahrzeugkommandanten losfahren · StVO beachten — Einsatzfahrer haben KEINEN Freibrief. Der Fahrer trägt die Verantwortung für Mannschaft und Fahrzeug!", "Auf der Anfahrt den Einsatzort über das Funkgerät erfragen", "Möglichst schnell fahren — der Kommandant gibt die Richtung vor", "Während der Fahrt schon die Schläuche vorbereiten"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 42 (Aufgaben Anfahrt)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 43 (Aufstellung)", "f": "Woran ist bei der Aufstellung des Fahrzeuges an der Einsatzstelle zu denken?", "opts": ["So nahe wie möglich an die Einsatzstelle, aber außerhalb des Gefahrenbereichs (Wärmestrahlung beachten) · Verkehrsbereiche und Aufstellflächen für Drehleitern/Rettungsfahrzeuge freihalten · Fahrzeug möglichst in Fluchtrichtung aufstellen · Fahrzeug absichern (Gefälle, Steigung, Verkehrswege) — zur Absicherung Blaulicht, Warnblinkanlage und Verkehrsleiteinrichtung einschalten, Einsatzstelle gemäß Richtlinie absichern.", "Möglichst nahe am Objekt, auch im Trümmerschatten", "Quer zur Fahrbahn abstellen, damit niemand durchkommt", "Den Motor abstellen, um Sprit zu sparen"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 43 (Aufstellung)"}, {"m": "5,5t-Lenkberechtigung", "src": "5,5t Vortrag Folie 28–29 (Verkehrsunfall mit Fw-Fahrzeug)", "f": "Was passiert bei einem Verkehrsunfall mit dem Feuerwehrfahrzeug — erste Schritte?", "opts": ["Sofort anhalten und Folgeschäden vermeiden · Unfallstelle absichern · verständigen: bei Verletzten Rettungsorganisation und Polizei · Rettungsmaßnahmen setzen (direkt: Retten/Erste Hilfe · indirekt: Notarzt verständigen) · weitere Verständigungen: Behörde (Gemeinde, BH), Straßenerhalter · Mitwirkung bei der Unfallursachen-Ermittlung · Verkehrsflächen nur im Einvernehmen mit Polizei/BH/Magistrat/Staatsanwaltschaft freimachen.", "Fahrzeug nur in die Werkstatt bringen und niemanden informieren", "Nur die Feuerwehrleitung informieren, die Exekutive braucht man nicht", "Bei kleinen Schäden einfach weiterfahren"], "r": 0, "e": "", "m2": "5,5t-Lenkberechtigung", "kategorie": "5_5t", "herkunft": "5,5t Vortrag Folie 28–29 (Verkehrsunfall mit Fw-Fahrzeug)"}], "karten": [{"b": "Grundlagen", "q": "Was ist beim Schutzweg verboten?", "a": "Das Überholen auf und unmittelbar vor ungeregelten Schutzwegen · das Vorbeifahren an Fahrzeugen, die angehalten haben, um Fußgänger überqueren zu lassen · das Halten und Parken auf der Bodenmarkierung · das Halten und Parken in den letzten 5 m vor der Bodenmarkierung aus der Sicht des ankommenden Verkehrs · bei Kolonnenverkehr darf man auf dem Übergang nicht anhalten.", "g": "Grundlagen"}, {"b": "Grundlagen", "q": "Wo müssen Sie vermehrt mit Kindern rechnen?", "a": "Im Bereich von Kindergärten, Schulen und Kinderspielplätzen.", "g": "Grundlagen"}, {"b": "Grundlagen", "q": "Wie werden Sie sich als Fahrzeuglenker gegenüber Kindern verhalten?", "a": "Ich richte meine Aufmerksamkeit verstärkt auf diese und fahre, falls notwendig, auch bremsbereit · ich fahre so, dass ich etwaige Fehler von Kindern ausgleichen kann · ich rechne damit, dass sie sich nicht situationsgerecht verhalten werden.", "g": "Grundlagen"}, {"b": "Grundlagen", "q": "Wie werden Sie sich als Fahrzeuglenker gegenüber älteren oder gebrechlichen Verkehrsteilnehmern verhalten?", "a": "Ich beobachte verstärkt das Verhalten dieser Personen und fahre, falls notwendig, auch bremsbereit · ich fahre so, dass ich etwaige Fehler ausgleichen kann.", "g": "Grundlagen"}, {"b": "Grundlagen", "q": "Wie ist der Abstand zum vorderen Fahrzeug (im Nichteinsatzfall) zu wählen?", "a": "Ca. 2–3 Sekunden oder ca. 50 m Abstand halten, denn wenn mich ein Fahrzeug überholt, dann kann es sich vor mir einordnen.", "g": "Grundlagen"}, {"b": "Technisches", "q": "Welche Kontrollen führen Sie bei Reifen vor Fahrtantritt durch?", "a": "Die Verformung des Reifens durch Sichtkontrolle prüfen · die Gleichmäßigkeit der Laufflächenabnützung", "g": "Technisches"}, {"b": "Technisches", "q": "Wie viel mm muss die Profiltiefe mindestens haben?", "a": "Mind. 2 mm", "g": "Technisches"}, {"b": "Technisches", "q": "Welche Nachteile und Gefahren kann es beim Fahren mit zu geringem Reifendruck geben?", "a": "Überhitzung des Reifens durch starkes Walken · Reifenbrand oder -platzer · Erhöhung des Kraftstoffverbrauches", "g": "Technisches"}, {"b": "Technisches", "q": "Wo darf man einen Radwechsel durchführen und was muss man beachten?", "a": "Es ist ein geeigneter Platz zu suchen, nicht auf der Fahrbahn! · Alarmblinkanlage einschalten · Warnweste anziehen · Feststellbremse anziehen, Gang einlegen, Unterlegkeile vorlegen · Radmuttern lockern · Fahrzeug abheben · Radmuttern abschrauben · Rad oder Räder abnehmen · Reserverad aufsetzen (beim Aufsetzen der Zwillingsräder ist auf den Ventilzugang zu achten) · Radmuttern anschrauben · Radmuttern kreuzweise festziehen", "g": "Technisches"}, {"b": "Technisches", "q": "Was ist eine Feststellbremse?", "a": "Es ist eine von der Betriebsbremse unabhängig zu betätigende Bremsanlage, mit der das Abrollen des Fahrzeuges dauernd verhindert werden kann.", "g": "Technisches"}, {"b": "Technisches", "q": "Was können Sie an der Betriebsbremse bei stehendem Fahrzeug überprüfen?", "a": "Den Leerweg, die Dichtheit, die Bremslichter und das Mehrkreisschutzventil", "g": "Technisches"}, {"b": "Technisches", "q": "Was ist bei einer Lenkung regelmäßig zu kontrollieren?", "a": "Der Flüssigkeitsstand im Ölbehälter der hydraulischen Lenkhilfe · das Lenkungsspiel, bei laufendem Motor darf kein deutlicher Leerweg spürbar sein · die Leichtgängigkeit · der Selbstrücklauf", "g": "Technisches"}, {"b": "Technisches", "q": "Ihr LKW zieht beim Geradeausfahren nach einer Seite. Welche Ursachen kann dies haben?", "a": "Zu geringer Reifendruck in einem der beiden Vorderreifen · die Lenkgeometrie ist verstellt · starker Seitenwind", "g": "Technisches"}, {"b": "Technisches", "q": "Welche Wartungs- und Kontrollarbeiten kann der Lenker an der Batterie selbst durchführen?", "a": "Kontrolle des Flüssigkeitsstandes · Säubern der Pole · Kabelanschlüsse und Batteriehalterungen auf festen Sitz prüfen", "g": "Technisches"}, {"b": "Technisches", "q": "Welche Auswirkungen kann eine rutschende Kupplung auf den Fahrbetrieb haben?", "a": "Die Beschleunigung des Fahrzeuges wird schlechter · die Motorbremsung wird geringer · die Wirkung der Motorstaubremse ist geringer", "g": "Technisches"}, {"b": "Technisches", "q": "Was kann der Lenker an der Kupplung überprüfen?", "a": "Den Leerweg (Totgang) · das vollständige Lösen · das vollständige Verbinden", "g": "Technisches"}, {"b": "Technisches", "q": "Welche Kaltstarteinrichtungen können bei einem Dieselmotor eingebaut sein?", "a": "Flammstartanlage · Heizflansch · Vorglühanlage", "g": "Technisches"}, {"b": "Technisches", "q": "Woran können Sie eine Störung in der Kaltstarteinrichtung des Dieselmotors erkennen?", "a": "Motor springt nicht an · beim Verglühen leuchtet die Vorglüh-Kontrolllampe nicht auf.", "g": "Technisches"}, {"b": "Technisches", "q": "Woran können Sie während der Fahrt Mängel im Schmiersystem des Dieselmotors erkennen?", "a": "Am Ölmanometer oder an der Öldruckkontrolllampe", "g": "Technisches"}, {"b": "Technisches", "q": "Während der Fahrt leuchtet die Öldruckkontrolllampe auf. Wie werden Sie sich verhalten?", "a": "Ich halte an und stelle den Motor ab · wenn genügend Motoröl in der Ölwanne ist, lasse ich den LKW abschleppen.", "g": "Technisches"}, {"b": "Technisches", "q": "Während der Fahrt leuchtet die Ladekontrollleuchte auf. Was schließen Sie daraus und wie verhalten Sie sich?", "a": "Strom wird nur mehr aus der Batterie entnommen · die Batterie wird nicht mehr geladen · ich kontrolliere den Keilriemen · wenn der Keilriemen nicht gerissen ist, fahre ich zur nächsten Werkstätte.", "g": "Technisches"}, {"b": "Technisches", "q": "Wie können Sie während der Fahrt feststellen, dass die Motorkühlung nicht einwandfrei funktioniert?", "a": "Das Fernthermometer zeigt in den roten Bereich · eine zusätzliche Kühlerkontrolllampe beim Fernthermometer leuchtet auf.", "g": "Technisches"}, {"b": "Technisches", "q": "Wie verhalten Sie sich, wenn Sie erkennen, dass die Motorkühlung ausgefallen ist?", "a": "Ich werde anhalten und kontrollieren, ob der Keilriemen richtig gespannt ist · ich kontrolliere, ob genügend Kühlflüssigkeit im Ausgleichsbehälter ist.", "g": "Technisches"}, {"b": "Technisches", "q": "Wie können Sie während der Fahrt feststellen, dass die Betriebsbremse defekt ist?", "a": "Die Bremswarnleuchte leuchtet auf · ich bemerke eine verringerte oder fehlende Bremswirkung.", "g": "Technisches"}, {"b": "Technisches", "q": "Wie verhalten Sie sich, wenn Sie einen Defekt an der Betriebsbremse feststellen?", "a": "Ich halte an und führe eine Standbremsprobe durch.", "g": "Technisches"}, {"b": "Technisches", "q": "Welche Vorteile hat die Luftfederung?", "a": "Schonung des Ladegutes · beim Kurvenfahren bleibt die Ladefläche nahezu waagrecht.", "g": "Technisches"}, {"b": "Technisches", "q": "Was können Sie an der Luftfederung eines LKW überprüfen?", "a": "Den Zustand der Federbälge durch Sichtkontrolle · die Dichtheit durch Abhorchen · das Gestänge der Niveauregelventile", "g": "Technisches"}, {"b": "Technisches", "q": "Welche Ursachen kann blauer Auspuffrauch haben?", "a": "Hoher Verschleiß am Motor · Ölabstreifring gebrochen · Dichtring undicht", "g": "Technisches"}, {"b": "Technisches", "q": "Welche Ursachen kann schwarzer Auspuffrauch haben?", "a": "Luftfilter stark verschmutzt · Treibstoffüberschuss · Motor überlastet", "g": "Technisches"}, {"b": "Technisches", "q": "Welche Ursachen kann weißer Auspuffrauch haben?", "a": "Wasserdampf nach Kaltstart · Zylinderkopfdichtung undicht, defekt · Steg- oder Büchsenriss im Motorzylinder", "g": "Technisches"}, {"b": "Technisches", "q": "Wozu dient das Mehrkreisschutzventil bei einer Druckluftbremse?", "a": "Zur Drucksicherung von Nebenverbrauchern · zur Erhaltung des Sicherungsdruckes bei Ausfall eines Kreises der Betriebsbremsanlage", "g": "Technisches"}, {"b": "Technisches", "q": "Welche Aufgabe hat das Mehrkreisschutzventil einer Druckluftbremse?", "a": "Es sichert den Druck in den anderen Vorratskreisen, wenn ein Vorratskreis ausfällt.", "g": "Technisches"}, {"b": "Technisches", "q": "Was verstehen Sie unter einer ALB-Regelung bei einer Druckluftbremsanlage?", "a": "Eine Anlage, welche die Bremskraft der Achsen nach dem Beladungszustand automatisch regelt.", "g": "Technisches"}, {"b": "Technisches", "q": "Wie durchfahren Sie eine Kurve mit dem LKW?", "a": "Ich werde vor der Kurve die Geschwindigkeit anpassen und erst im Kurvenauslauf beschleunigen · in der Kurve mache ich kurze Kontrollblicke in den Rückspiegel.", "g": "Technisches"}, {"b": "Technisches", "q": "Sie fahren mit Ihrem LKW in eine Kurve. Welche Faktoren erhöhen die Kippgefahr?", "a": "Eine verrutschende Ladung · eine hohe Schwerpunktlage · ruckartiges Lenken · halbvoller Wassertank", "g": "Technisches"}, {"b": "Technisches", "q": "Wonach richten Sie die Fahrgeschwindigkeit in einer engen Kurve?", "a": "Nach dem Kurvenradius und der Querneigung der Fahrbahn · nach der Höhe des Gesamtschwerpunktes des LKW · nach dem Fahrbahnzustand", "g": "Technisches"}, {"b": "Technisches", "q": "Sie befahren mit Ihrem LKW eine längere Gefällestrecke. Wann verwenden Sie die Betriebsbremse?", "a": "Vor und während des Zurückschaltens in einen niedrigen Gang · zum Anbremsen vor Kurven · beim Anbremsen bis zum Stillstand", "g": "Technisches"}, {"b": "Technisches", "q": "Sie fahren mit Ihrem LKW auf einer Freilandstraße mit einem Gefälle von 9 %. Wie verhalten Sie sich in dieser Situation?", "a": "Ich werde rechtzeitig auf einen niedrigen Gang schalten, damit ich mit der Motorbremswirkung meine Geschwindigkeit halten kann · ich bremse mit der Motorstaubremse auch über eine längere Strecke · falls vorhanden, bremse ich mit der Wirbelstrombremse.", "g": "Technisches"}, {"b": "Technisches", "q": "Sie befahren mit Ihrem LKW eine Steigung. Wann müssen Sie zurückschalten?", "a": "Wenn die Motordrehzahl trotz Vollgas unter den „grünen Bereich“ des Drehzahlmessers zu sinken droht.", "g": "Technisches"}, {"b": "Technisches", "q": "Sie erkennen, dass sich hinter Ihrem LKW eine lange Kolonne gebildet hat. Wie werden Sie sich im Nichteinsatzfall verhalten?", "a": "Ich sollte an geeigneter Stelle anhalten und die Fahrzeuge hinter mir vorbeizulassen · ich werde auf die Fahrzeuge hinter mir besonders achten, um bei riskanten Überholmanövern rasch reagieren zu können.", "g": "Technisches"}, {"b": "Technisches", "q": "Wie erkennen Sie, dass nicht genügend Motoröl vorhanden ist?", "a": "Aufleuchten der Ölstandskontrolleleuchte, wenn eine vorhanden ist · bei abgestelltem Motor durch den Ölmessstab", "g": "Technisches"}, {"b": "Technisches", "q": "Welche Gefahr besteht, wenn Sie sich bei aufleuchtender Öldruckkontrollleuchte falsch verhalten?", "a": "Bei Weiterfahrt kann es zu einem Motorschaden kommen · bei einem Motorschaden kann das Fahrzeug ins Schleudern kommen · wenn das Fahrzeug auf der Fahrbahn abgestellt wird und nicht abgesichert ist, kann es zu einem Auffahrunfall kommen.", "g": "Technisches"}, {"b": "Technisches", "q": "Was ist beim Überholen von Fahrzeugen zu beachten?", "a": "Den größeren Platzbedarf berücksichtigen · unter Umständen mit längeren Bremswegen rechnen · rechtzeitig zurückschalten · mit einer geringeren Beschleunigung rechnen · den längeren Überholweg und die größere Überholsichtweite berücksichtigen · den Seitenabstand beachten, im Besonderen beim Überholen von Rad- und Mopedfahrern", "g": "Technisches"}, {"b": "Technisches", "q": "Was verstehen Sie unter einer Druckluftbremsanlage?", "a": "Eine Bremsanlage, bei der die Bremskraft durch Druckluft erzeugt wird.", "g": "Technisches"}, {"b": "Technisches", "q": "Was kann die Ursache sein, wenn der Kompressor zu wenig Luft fördert?", "a": "Luftfilter kann verlegt sein · Keilriemen können rutschen · der Kompressor kann Kompressionsverluste haben.", "g": "Technisches"}, {"b": "Technisches", "q": "Welche Aufgabe hat der Lufttrockner einer Druckluftbremse?", "a": "Der vom Kompressor geförderten Luft die Feuchtigkeit zu entziehen.", "g": "Technisches"}, {"b": "Technisches", "q": "Wie können Sie im Winter die Gefahr des Einfrierens einer Druckluftbremsanlage verringern?", "a": "Die Frostschutzeinrichtung auf Winterbetrieb stellen · die Luftbehälter täglich entwässern.", "g": "Technisches"}, {"b": "Technisches", "q": "Die Warnleuchte für die Betriebsbremsanlage leuchtet auf. Wie viele Bremsungen können Sie noch durchführen?", "a": "Noch mind. 4 Vollbremsungen", "g": "Technisches"}, {"b": "Technisches", "q": "Der Vorratsdruck einer Druckluftbremse fällt bei einer Vollbremsung um mehr als 0,7 bar ab. Welche Ursachen kann dies haben?", "a": "Die Bremsbeläge können abgenutzt sein · die Vorratsbehälter können stark eingebeult sein · Wasser kann in den Vorratsbehältern sein.", "g": "Technisches"}, {"b": "Feuerwehrspezifisches", "q": "Worauf ist beim Fahren mit Tanklöschfahrzeugen betreffend des Wassertankinhaltes zu beachten?", "a": "Mit vollem bzw. leerem Tank fahren, da es bei Kurvenfahrt und Bremsmanöver mit halbvollem Wassertank durch Schwabbelbewegungen zu unkontrollierbaren Schwerpunktverlagerungen kommen kann · sollte die Rückfahrt vom Einsatz mit teilgefülltem Wassertank angetreten werden, ist mit besonderer Vorsicht bis zur nächsten Füllmöglichkeit zu fahren · hohen Schwerpunkt beachten.", "g": "Feuerwehrspezifisches"}, {"b": "Feuerwehrspezifisches", "q": "Wie sind Feuerwehrfahrzeuge verkehrs- und betriebssicher zu erhalten und wie ist dies zu überprüfen bzw. zu dokumentieren?", "a": "Durchführung von Probefahrten mind. alle 14 Tage über mind. 10 km mit anschließendem Eintrag ins Fahrtenbuch und Fahrzeugkontrolle anhand der Checkliste.", "g": "Feuerwehrspezifisches"}, {"b": "Feuerwehrspezifisches", "q": "Wie (mit welchen Geräten) sind Einsatzstellen abzusichern?", "a": "Abhängig von der Witterung und den Straßenverhältnissen · im Ortsgebiet: 50 m · auf Freilandstraßen: 150–250 m · auf Autobahnen: 250–400 m. Zusätzlich zur StVO-Ausrüstung (Pannendreieck) stehen zur Verfügung: Verkehrsleitkegel · Triopan-Faltsignale · orange Blitzleuchten · hochreflektierende Warnüberwürfe · Verkehrsleiteinrichtungen am Feuerwehrfahrzeug · Verkehrsregler mit spezieller Ausrüstung (Anhaltestab, Einsatzbekleidung, Warnüberwurf).", "g": "Feuerwehrspezifisches"}, {"b": "Feuerwehrspezifisches", "q": "Wo sind Einsatzstellen abzusichern (Kurven, Kuppen)?", "a": "In Kurven und auf in zwei Richtungen befahrenen Straßen: Gegenverkehr sichern · vor Kuppen in ausreichendem Abstand sichern.", "g": "Feuerwehrspezifisches"}, {"b": "Feuerwehrspezifisches", "q": "Was ist nach der Rückfahrt zu tun?", "a": "Wiederherstellen der Einsatzbereitschaft · Reinigung des Fahrzeuges · Führen des Fahrtenbuches · Kontrollen am Fahrzeug · Einrückmeldung", "g": "Feuerwehrspezifisches"}, {"b": "Feuerwehrspezifisches", "q": "Welche Kontrollen sind vor jeder Ausfahrt durchzuführen?", "a": "Einsatzbereitschaft des Fahrzeuges muss immer gegeben sein · Fahrtauglichkeit des Fahrers muss gegeben sein · Fahrzeug nicht überladen · Fahrzeugkontrolle · Abstecken der Versorgungsleitungen und der Abgasleitung · Zuteilung der Mannschaft abwarten (Fahrer ist nicht GK, GK ist nicht Fahrer) · Mindestbesatzung · Öffnen der Garagentore bis zum Anschlag / Sichern des Tores · Anlegen der Sicherheitsgurte · Fahrzeugtüren schließen · Abfahrt auf Weisung des Gruppenkommandanten", "g": "Feuerwehrspezifisches"}, {"b": "Feuerwehrspezifisches", "q": "Was ist bei der Auswahl des Aufstellungsortes bei der Einsatzstelle zu beachten?", "a": "Gefahrenbereich meiden · Fluchtrichtung · auf der Straßenseite der Einsatzstelle · nicht im Trümmerschatten · Rückzugsmöglichkeiten", "g": "Feuerwehrspezifisches"}, {"b": "Feuerwehrspezifisches", "q": "Aufgabenteilung Lenker – Fahrzeugkommandant", "a": "Lenker: Betätigen der Warnsignale · konzentriere dich auf die Fahrt und nicht auf Funkmeldungen · Fahrgeschwindigkeit den Verhältnissen anpassen · Fahrverhalten des Fahrzeuges (hoher Schwerpunkt, Wassertank, Witterung). — Fahrzeugkommandant: Prüfen der Fahrtauglichkeit · Einweisen · Sichern · Funkverkehr · Anfahrtstrecke bekannt geben · Fahrzeugruhe.", "g": "Feuerwehrspezifisches"}, {"b": "Rechtliches", "q": "Was versteht man unter einem Feuerwehrfahrzeug, was unter einem Einsatzfahrzeug? Ist ein VW-Golf, der auf eine Feuerwehr zugelassen ist, ein Feuerwehrfahrzeug?", "a": "Ein Feuerwehrfahrzeug ist ein nach Bauart und Ausrüstung ausschließlich oder vorwiegend zur Verwendung für Feuerwehren bestimmtes Fahrzeug. Ein VW Golf, der nicht entsprechend umgebaut ist, gilt nicht als Feuerwehrfahrzeug im Sinne des KFG. Ein Fahrzeug gilt als Einsatzfahrzeug, wenn entweder Blaulicht oder Folgetonhorn eingeschaltet sind, für die Dauer der Verwendung eines dieser Signale.", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Ist der Lenker eines Feuerwehrfahrzeuges auch außerhalb von Einsatzfahrzeugen an bestimmte Verkehrsvorschriften nicht gebunden?", "a": "Ja, bei „Allgemeines Fahrverbot“, „Einfahrt verboten“ und „Vorgeschriebene Fahrtrichtung“, wenn Ausnahmen für andere Kraftfahrzeuge und Fuhrwerke auf Zusatztafeln angebracht sind.", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Wie viele Personen dürfen Sie in einem Feuerwehrfahrzeug mitnehmen?", "a": "Die im Zulassungsschein eingetragene Zahl ist maßgeblich; nur bei Fahrten zu Orten eines dringenden Einsatzes und auf Rückfahrten von solchen Orten mit Feuerwehrfahrzeugen darf diese Anzahl überschritten werden (§ 106 Abs. 3 KFG i.V.m. § 107 Abs. 3).", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Unter welchen Voraussetzungen müssen Kinder in Feuerwehrfahrzeugen angegurtet werden?", "a": "Bei Fahrzeugen bis 3,5 to hzl. Gesamtgewicht muss der Lenker darauf achten, dass Kinder unter 12, die kleiner als 1,50 m sind, auch in Feuerwehrfahrzeugen angegurtet werden, sofern diese mit Sicherheitsgurten ausgerüstet sind. Ausnahmen: besondere Verkehrslage, die den Nichtgebrauch rechtfertigt, oder bei Beförderung bei Einsatzfahrten mit Blaulicht oder Folgetonhorn.", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Müssen sich Erwachsene im Feuerwehrfahrzeug angurten?", "a": "Ja, wenn der Sitzplatz mit einem Sicherheitsgurt ausgerüstet ist. Ausnahme: bei Einsatzfahrzeugen (Blaulicht oder Folgetonhorn eingeschaltet), wenn der Gebrauch des Sicherheitsgurtes mit dem Zweck der Fahrt unvereinbar ist (z. B. wenn im Fahrzeug schon Atemschutzausrüstung angelegt wird).", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Ist der Lenker dafür verantwortlich, dass sich die übrigen Insassen angurten?", "a": "Lenker und beförderte Personen sind je für sich zum Gebrauch des Sicherheitsgurtes verpflichtet, nur bei Kindern ist der Lenker dafür verantwortlich.", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Dürfen Sie mit einem Feuerwehrfahrzeug in einer 30 km/h Zone mit 50 km/h oder mit 80 km/h fahren bzw. wie schnell darf man dort fahren?", "a": "Bei Einsatzfahrten sind Feuerwehrfahrzeuge auf Fahrten zu Orten eines dringenden Einsatzes nicht an Geschwindigkeitsbeschränkungen gemäß StVO oder KDV gebunden. Die Fahrgeschwindigkeit ist jedoch den konkreten Verhältnissen anzupassen; auch der Grundsatz „Fahren auf Sicht“ ist zu beachten.", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Dürfen bei Einsatzübungsfahrten Blaulicht und Folgetonhorn verwendet werden und Geschwindigkeiten überschritten werden?", "a": "Ja, aber nur wenn es der Zweck der Einsatzübungsfahrt erfordert und sonst in geeigneter Weise für die Verkehrssicherheit vorgesorgt ist (z. B. Absicherung der Strecke durch Streckenposten).", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Hat ein Feuerwehrfahrzeug immer Vorrang?", "a": "Nein, nur wenn Blaulicht oder Folgetonhorn eingeschaltet sind.", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Wann dürfen Sie die Warnzeichen einschalten?", "a": "Nur bei Gefahr im Verzug, z. B. bei Fahrten zum und vom Ort der dringenden Hilfeleistung oder zum Ort des sonstigen dringenden Einsatzes. Das Blaulicht darf aus Gründen der Verkehrssicherheit auch am Ort des Einsatzes verwendet werden.", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Ist der Lenker eines Einsatzfahrzeuges an Verkehrsverbote oder Verkehrsbeschränkungen gebunden?", "a": "Bei Einsatzfahrten (Blaulicht oder Folgetonhorn) ist er grundsätzlich nicht an Verkehrsverbote oder Verkehrsbeschränkungen gebunden; er darf hierbei jedoch nicht Personen gefährden oder Sachen beschädigen. Bei rotem Licht darf man nur in eine Kreuzung einfahren, wenn man vorher anhält und sich überzeugt, dass hierbei nicht Menschen gefährdet oder Sachen beschädigt werden. Einbahnstraßen dürfen in der Gegenrichtung befahren werden, aber nur, wenn der Einsatzort anders nicht oder nicht in der gebotenen Zeit erreichbar ist oder wenn Ausnahmen für andere Kraftfahrzeuge oder Fuhrwerke bestehen.", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Dürfen Sie als Einsatzfahrer gegen die Einbahn fahren?", "a": "Nur, wenn der Einsatzort anders nicht oder nicht in der gebotenen Zeit erreichbar ist oder wenn Ausnahmen für andere Kraftfahrzeuge bestehen (§ 26 Abs. 3 StVO). — Zusatzfrage: Haben Sie dann Vorrang gegenüber entgegenkommenden Fahrzeugen? Ja. — Zusatzfrage: Wie haben sich die anderen Verkehrsteilnehmer zu verhalten? Platz machen.", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Welche Probleme können auftauchen, wenn Sie als Einsatzfahrer unberechtigt gegen die Einbahn fahren?", "a": "Verwaltungsstrafverfahren · Mitverschulden bei einem Unfall", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "In welcher Reihenfolge haben beim Zusammentreffen von verschiedenen Einsatzfahrzeugen diese Vorrang?", "a": "Rettungsfahrzeuge · Fahrzeuge der Feuerwehr · Fahrzeuge des Sicherheitsdienstes · sonstige Einsatzfahrzeuge", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Wie haben sich alle Straßenbenützer einem herannahenden Einsatzfahrzeug gegenüber zu verhalten?", "a": "Platz machen, Vorrang geben", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Müssen Sie als Einsatzfahrer bei einer Kreuzung mit Rotlicht anhalten?", "a": "Ja, nur nach dem Anhalten und Überzeugen, dass niemand gefährdet wird, darf Rotlicht überfahren werden.", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Oberlöschmeister Meier fährt mit Blaulicht zur Pizzeria, weil seine Pizza kalt wird. Hat er gegenüber anderen Verkehrsteilnehmern Vorrang?", "a": "Ja, die Vorrangregelung knüpft nicht daran an, ob jemand zu Recht oder zu Unrecht Blaulicht oder Folgetonhorn eingeschaltet hat. — Zusatzfrage: Hat Oberlöschmeister Meier irgendwelche Konsequenzen zu befürchten? Ja, ein Verwaltungsstrafverfahren wegen Verstoßes gegen § 26 Abs. 1 KFG i.V.m. § 134 KFG; Mitverschulden im Falle eines Unfalls.", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Hat der Einsatzfahrer auch Vorrang bei einer ampelgeregelten Kreuzung bei Rotlicht?", "a": "Nein, in diesem Fall muss er anhalten und sich überzeugen, dass er niemanden gefährdet.", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Wer ist schuld, wenn Sie als Einsatzfahrer bei Rot in die Kreuzung einfahren und es kommt zu einem Unfall?", "a": "Der Einsatzfahrer; unter Umständen trifft den anderen ein Mitverschulden, wenn er zu spät gebremst hat oder zu schnell gefahren ist.", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Welche Dokumente haben Sie beim Lenken eines Feuerwehrfahrzeuges der Klasse C mitzuführen?", "a": "Den Feuerwehrführerschein und den Führerschein; beides ist auf Verlangen der Exekutive zur Überprüfung auszuhändigen (§ 14 Abs. 1 FSG).", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Welche Alkoholbestimmungen gibt es für Feuerwehrfahrzeuge?", "a": "Bis 7,5 t höchstzulässige Gesamtmasse: 0,5 ‰; über 7,5 t höchstzulässige Gesamtmasse: mit Feuerwehrführerschein 0,5 ‰; ohne Feuerwehrführerschein 0,1 ‰ (§ 32a Abs. 6 FSG).", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Dürfen Sie mit einem Feuerwehrführerschein mehr als 8 Personen im Feuerwehrfahrzeug mitführen, obwohl Sie keinen Busführerschein (Lenkberechtigung der Klasse D) besitzen?", "a": "Ja", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Unter welchen Voraussetzungen dürfen mehr als 8 Personen in einem Feuerwehrfahrzeug befördert werden?", "a": "Das Fahrzeug muss dafür laut Zulassungsschein geeignet sein, der Lenker muss entweder eine zivile Lenkberechtigung der Klasse D oder eine zivile Lenkberechtigung der Klasse B und zusätzlich einen Feuerwehrführerschein aufweisen (§ 1 Abs. 3 FSG).", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Dürfen Sie mit einer zivilen Lenkberechtigung B und einem Feuerwehrführerschein einen zivilen LKW lenken?", "a": "Nein", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Dürfen Sie mit einem Feuerwehrfahrzeug ohne Vignette oder Go-Box eine mautpflichtige Autobahn befahren?", "a": "Ja (Feuerwehrfahrzeuge, an denen Blaulicht angebracht ist, sind gemäß § 5 Abs. 1 Bundesstraßen-Mautgesetz 2002 von der Maupflicht ausgenommen).", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Wie bzw. mit welchen Abständen sind Einsatzstellen abzusichern?", "a": "Abhängig von der Witterung und den Straßenverhältnissen, im Ortsgebiet jedoch mindestens 50 m, auf Freilandstraßen 150 m bis 250 m und auf Autobahnen 250 m bis 400 m.", "g": "Rechtliches"}, {"b": "Rechtliches", "q": "Was passiert mit Ihrem Feuerwehrführerschein, wenn Ihnen die zivile Lenkberechtigung entzogen wird?", "a": "Wird für die Dauer der Entziehung ungültig (§ 32a Abs. 4 FSG).", "g": "Rechtliches"}], "merkhilfen": [{"t": "Der Feuerwehrführerschein (OÖ): <b>12 Einheiten Theorieausbildung</b> in einer Fahrschule mit „Feuerwehrführerschein-Lehrgang“ · <b>2 Fahrlektionen</b> in der jeweiligen Fahrschule (mit dem internen Fahrausbilder) · <b>10 Fahrlektionen</b> mit dem Feuerwehrfahrzeug (über 7,5 t hzG) der eigenen Feuerwehr. Prüfung immer Samstag, <b>85 €</b> Prüfungsgebühr, mit dem LKW der Feuerwehr. <i>Quelle: RL Führerscheinausbildung (6.11.001) + Ausbildungsplan (6.11.002).</i>", "g": "Allgemein"}, {"t": "Voraussetzungen: zivile <b>Lenkberechtigung B</b> · <b>ärztliche Untersuchung für die Klasse C</b> (zum Prüfungszeitpunkt max. 18 Monate alt) · <b>Zustimmung des Kommandanten</b> · interner Fahrausbilder (seit 7 Jahren Klasse B, mind. 2 Einsatz-/Übungsfahrten in 6 Monaten). Achtung: Hat die Feuerwehr nur ein Fahrzeug zwischen 5,6 und 7,5 t, muss die Ausbildung mit einem Fahrzeug über 7,5 t einer anderen Feuerwehr erfolgen! <i>Quelle: Ausbildungsplan (6.11.002), Checkliste.</i>", "g": "Allgemein"}, {"t": "Prüfungsgespräch (§ 3 Abs. 2 FSG-FRV): 4 Themenbereiche — <b>1.</b> kraftfahrrechtliche und straßenpolizeiliche Bestimmungen für Einsatzfahrzeuge · <b>2.</b> ausreichendes Verständnis für die Fahrzeugtechnik (Fehlererkennung, Fehlerbegrenzung, einfache Wartung) · <b>3.</b> Fahrphysik von Feuerwehrfahrzeugen · <b>4.</b> Absicherung und richtiges Verhalten am Einsatzort. <i>Quelle: Prüfungsprotokoll in 6.11.002.</i>", "g": "Allgemein"}, {"t": "Prüfungsfahrt: mind. <b>45 Minuten</b> mit einem Feuerwehrfahrzeug über 7.500 kg hzG — Überprüfungen am Fahrzeug (inkl. Blaulicht), Fahrübungen (Umkehren, Rückwärtsfahren, Anfahren auf Steigungen, Ein-/Ausfahren in Parklücken) und Bremsübungen (Gefahrenbremsungen). <i>Quelle: RL Führerscheinausbildung (6.11.001).</i>", "g": "Allgemein"}, {"t": "Alkohol am Feuerwehrfahrzeug: bis <b>7,5 t hzG: 0,5 ‰</b> · über <b>7,5 t</b>: mit Feuerwehrführerschein <b>0,5 ‰</b>, ohne <b>0,1 ‰</b> (§ 32a Abs. 6 FSG). Feuerwehrführerschein + zivile Lenkberechtigung B erlauben <b>B+C+D</b> für Feuerwehrfahrzeuge — mehr als 8 Personen nur, wenn das Fahrzeug laut Zulassungsschein geeignet ist.", "g": "Rechtliches"}, {"t": "Vorrang-Kette: <b>Rettungsfahrzeuge → Fahrzeuge der Feuerwehr → Sicherheitsdienst → sonstige Einsatzfahrzeuge</b>. Einsatzfahrzeug = Blaulicht ODER Folgetonhorn eingeschaltet (für die Dauer der Verwendung). Bei Rot: anhalten, überzeugen, erst dann einfahren. Gegen die Einbahn nur, wenn der Einsatzort anders nicht oder nicht rechtzeitig erreichbar ist.", "g": "Rechtliches"}, {"t": "Einsatzstelle absichern: Ortsgebiet mind. <b>50 m</b> · Freilandstraße <b>150–250 m</b> · Autobahn <b>250–400 m</b> (witterungs- und straßenabhängig). In Kurven den Gegenverkehr sichern, vor Kuppen in ausreichendem Abstand. Mittel: Verkehrsleitkegel, Triopan-Faltsignale, orange Blitzleuchten, Warnüberwürfe, Verkehrsregler.", "g": "Feuerwehrspezifisches"}, {"t": "TLF-Wassertank: mit <b>vollem oder leerem Tank</b> fahren — halb voll = Schwabbelbewegungen = unkontrollierbare Schwerpunktverlagerung bei Kurven und Bremsmanövern. Mit teilgefülltem Tank vom Einsatz zurück: besondere Vorsicht bis zur nächsten Füllmöglichkeit. Hoher Schwerpunkt beachten!", "g": "Feuerwehrspezifisches"}, {"t": "Abstand im Nichteinsatzfall: <b>ca. 2–3 Sekunden oder ca. 50 m</b>. Bei Gefälle 9 %: rechtzeitig niedrigen Gang schalten, Motorstaubremse/Wirbelstrombremse nutzen, Betriebsbremse nur zum Anbremsen und Zurückschalten. Bei langer Kolonne hinter dir (Nichteinsatzfall): an geeigneter Stelle anhalten und vorbeilassen.", "g": "Grundlagen"}, {"t": "Auspuffrauch lesen: <b>blau</b> = hoher Motorschleiß, Ölabstreifring gebrochen, Dichtring undicht · <b>schwarz</b> = Luftfilter verschmutzt, Treibstoffüberschuss, Motor überlastet · <b>weiß</b> = Wasserdampf nach Kaltstart, Zylinderkopfdichtung defekt, Steg-/Büchsenriss.", "g": "Technisches"}, {"t": "Warnzeichen-Bestimmungen (KFG): Warnzeichen nur bei <b>Gefahr im Verzug</b> — Fahrten zum und vom Ort der dringenden Hilfeleistung. Blaulicht darf aus Gründen der Verkehrssicherheit auch am Einsatzort verwendet werden. Bei Einsatzübungsfahrten nur, wenn es der Übungszweck erfordert und für die Verkehrssicherheit vorgesorgt ist (z. B. Streckenposten).", "g": "Rechtliches"}, {"t": "<b>5,5t — der WOLKE-Check vor Fahrantritt</b> (Vortrag Folie 7–13): <b>W</b>asser (Kühlwasser Frostschutz −30 °C · Scheibenwaschanlage · Wischerblätter · Löschwassertank: kein abgestandenes Wasser, Tankheizung · Pumpen und Leitungen) · <b>O</b>l (Motor-/Getriebeöl, Bremsflüssigkeit — Wechsel spätestens nach 2 Jahren) · <b>L</b>uft (Reifendruck auch Reserverad · Profiltiefe LKW 2,0 mm / PKW 1,6 mm / Winterreifen 5,0 mm · Zustand) · <b>K</b>raftstoff (immer voll tanken · Probelauf Feuerlöschpumpe · Winterdiesel rechtzeitig — Kanisterfarben: Benzin = rot · Gemisch = rot mit blauen Streifen · Diesel = gelb) · <b>E</b>lektrik (Verbraucher · Scheinwerfereinstellung · Keilriemen auf Risse/Spannung) + Auspuffanlage. Die Überprüfung macht der jeweilige Lenker laut Betriebsanleitung — bei der Fw nach jeder Inbetriebnahme, mindestens 1 x monatlich. <i>Quelle: 5,5t-Vortrag 6.11.004 (44 Folien).</i>", "g": "Allgemein"}, {"t": "<b>5,5t-Berechtigung — Verfahren & Prüfung</b>: Ausbildung + Prüfung komplett in der Feuerwehr (Ausbilder/Prüfer von der LFS bestellt, dürfen nicht dieselbe Person sein). Theorie: mind. <b>3 UE</b> (StVO-Einsatzfahrerrecht, Fahrzeugtechnik, Fahrphysik, Gefahrenlehre/Partnerkunde) — Prüfung: <b>20 Fragen, mind. 16 richtig</b>. Praxis: mind. <b>5 UE</b> (Einschulung, Zustandsüberprüfung, Fahrübungen) — Prüfung: Fahrzeug-Überprüfungen + Langsamfahrübungen (Einparken, Umkehren, Rückwärtsfahren) + Prüfungsfahrt öffentlicher Verkehr <b>mind. 25 Minuten</b>, keine groben StVO-Verstöße. Fahrzeug mit <b>„L“-Tafeln</b> (weiß auf hellblau, aus beiden Richtungen) kennzeichnen. Bestätigung = <b>gelbe Scheckkarte</b>, nur gültig mit aufrechter Klasse B, bei Fahrten mitzuführen. Voraussetzung: NICHT im Besitz von C1/C sein. <i>Quelle: Dienstanweisung + FSG-FRV §§ 5–6 (BGBl. II 79/2011).</i>", "g": "Allgemein"}], "katalog_html": "<div class=\"zmod\">Merkhilfen — Ausbildung, Prüfung & Recht</div><div class=\"merkkachel\">Der Feuerwehrführerschein (OÖ): <b>12 Einheiten Theorieausbildung</b> in einer Fahrschule mit „Feuerwehrführerschein-Lehrgang“ · <b>2 Fahrlektionen</b> in der jeweiligen Fahrschule (mit dem internen Fahrausbilder) · <b>10 Fahrlektionen</b> mit dem Feuerwehrfahrzeug (über 7,5 t hzG) der eigenen Feuerwehr. Prüfung immer Samstag, <b>85 €</b> Prüfungsgebühr, mit dem LKW der Feuerwehr. <i>Quelle: RL Führerscheinausbildung (6.11.001) + Ausbildungsplan (6.11.002).</i></div><div class=\"merkkachel\">Voraussetzungen: zivile <b>Lenkberechtigung B</b> · <b>ärztliche Untersuchung für die Klasse C</b> (zum Prüfungszeitpunkt max. 18 Monate alt) · <b>Zustimmung des Kommandanten</b> · interner Fahrausbilder (seit 7 Jahren Klasse B, mind. 2 Einsatz-/Übungsfahrten in 6 Monaten). Achtung: Hat die Feuerwehr nur ein Fahrzeug zwischen 5,6 und 7,5 t, muss die Ausbildung mit einem Fahrzeug über 7,5 t einer anderen Feuerwehr erfolgen! <i>Quelle: Ausbildungsplan (6.11.002), Checkliste.</i></div><div class=\"merkkachel\">Prüfungsgespräch (§ 3 Abs. 2 FSG-FRV): 4 Themenbereiche — <b>1.</b> kraftfahrrechtliche und straßenpolizeiliche Bestimmungen für Einsatzfahrzeuge · <b>2.</b> ausreichendes Verständnis für die Fahrzeugtechnik (Fehlererkennung, Fehlerbegrenzung, einfache Wartung) · <b>3.</b> Fahrphysik von Feuerwehrfahrzeugen · <b>4.</b> Absicherung und richtiges Verhalten am Einsatzort. <i>Quelle: Prüfungsprotokoll in 6.11.002.</i></div><div class=\"merkkachel\">Prüfungsfahrt: mind. <b>45 Minuten</b> mit einem Feuerwehrfahrzeug über 7.500 kg hzG — Überprüfungen am Fahrzeug (inkl. Blaulicht), Fahrübungen (Umkehren, Rückwärtsfahren, Anfahren auf Steigungen, Ein-/Ausfahren in Parklücken) und Bremsübungen (Gefahrenbremsungen). <i>Quelle: RL Führerscheinausbildung (6.11.001).</i></div><div class=\"merkkachel\">Alkohol am Feuerwehrfahrzeug: bis <b>7,5 t hzG: 0,5 ‰</b> · über <b>7,5 t</b>: mit Feuerwehrführerschein <b>0,5 ‰</b>, ohne <b>0,1 ‰</b> (§ 32a Abs. 6 FSG). Feuerwehrführerschein + zivile Lenkberechtigung B erlauben <b>B+C+D</b> für Feuerwehrfahrzeuge — mehr als 8 Personen nur, wenn das Fahrzeug laut Zulassungsschein geeignet ist.</div><div class=\"merkkachel\">Vorrang-Kette: <b>Rettungsfahrzeuge → Fahrzeuge der Feuerwehr → Sicherheitsdienst → sonstige Einsatzfahrzeuge</b>. Einsatzfahrzeug = Blaulicht ODER Folgetonhorn eingeschaltet (für die Dauer der Verwendung). Bei Rot: anhalten, überzeugen, erst dann einfahren. Gegen die Einbahn nur, wenn der Einsatzort anders nicht oder nicht rechtzeitig erreichbar ist.</div><div class=\"merkkachel\">Einsatzstelle absichern: Ortsgebiet mind. <b>50 m</b> · Freilandstraße <b>150–250 m</b> · Autobahn <b>250–400 m</b> (witterungs- und straßenabhängig). In Kurven den Gegenverkehr sichern, vor Kuppen in ausreichendem Abstand. Mittel: Verkehrsleitkegel, Triopan-Faltsignale, orange Blitzleuchten, Warnüberwürfe, Verkehrsregler.</div><div class=\"merkkachel\">TLF-Wassertank: mit <b>vollem oder leerem Tank</b> fahren — halb voll = Schwabbelbewegungen = unkontrollierbare Schwerpunktverlagerung bei Kurven und Bremsmanövern. Mit teilgefülltem Tank vom Einsatz zurück: besondere Vorsicht bis zur nächsten Füllmöglichkeit. Hoher Schwerpunkt beachten!</div><div class=\"merkkachel\">Abstand im Nichteinsatzfall: <b>ca. 2–3 Sekunden oder ca. 50 m</b>. Bei Gefälle 9 %: rechtzeitig niedrigen Gang schalten, Motorstaubremse/Wirbelstrombremse nutzen, Betriebsbremse nur zum Anbremsen und Zurückschalten. Bei langer Kolonne hinter dir (Nichteinsatzfall): an geeigneter Stelle anhalten und vorbeilassen.</div><div class=\"merkkachel\">Auspuffrauch lesen: <b>blau</b> = hoher Motorschleiß, Ölabstreifring gebrochen, Dichtring undicht · <b>schwarz</b> = Luftfilter verschmutzt, Treibstoffüberschuss, Motor überlastet · <b>weiß</b> = Wasserdampf nach Kaltstart, Zylinderkopfdichtung defekt, Steg-/Büchsenriss.</div><div class=\"merkkachel\">Warnzeichen-Bestimmungen (KFG): Warnzeichen nur bei <b>Gefahr im Verzug</b> — Fahrten zum und vom Ort der dringenden Hilfeleistung. Blaulicht darf aus Gründen der Verkehrssicherheit auch am Einsatzort verwendet werden. Bei Einsatzübungsfahrten nur, wenn es der Übungszweck erfordert und für die Verkehrssicherheit vorgesorgt ist (z. B. Streckenposten).</div><div class=\"zmod\">Grundlagen — Fragen & Antworten</div><div class=\"zq\">Was ist beim Schutzweg verboten?</div><ul><li>Das Überholen auf und unmittelbar vor ungeregelten Schutzwegen · das Vorbeifahren an Fahrzeugen, die angehalten haben, um Fußgänger überqueren zu lassen · das Halten und Parken auf der Bodenmarkierung · das Halten und Parken in den letzten 5 m vor der Bodenmarkierung aus der Sicht des ankommenden Verkehrs · bei Kolonnenverkehr darf man auf dem Übergang nicht anhalten.</li></ul><div class=\"zq\">Wo müssen Sie vermehrt mit Kindern rechnen?</div><ul><li>Im Bereich von Kindergärten, Schulen und Kinderspielplätzen.</li></ul><div class=\"zq\">Wie werden Sie sich als Fahrzeuglenker gegenüber Kindern verhalten?</div><ul><li>Ich richte meine Aufmerksamkeit verstärkt auf diese und fahre, falls notwendig, auch bremsbereit · ich fahre so, dass ich etwaige Fehler von Kindern ausgleichen kann · ich rechne damit, dass sie sich nicht situationsgerecht verhalten werden.</li></ul><div class=\"zq\">Wie werden Sie sich als Fahrzeuglenker gegenüber älteren oder gebrechlichen Verkehrsteilnehmern verhalten?</div><ul><li>Ich beobachte verstärkt das Verhalten dieser Personen und fahre, falls notwendig, auch bremsbereit · ich fahre so, dass ich etwaige Fehler ausgleichen kann.</li></ul><div class=\"zq\">Wie ist der Abstand zum vorderen Fahrzeug (im Nichteinsatzfall) zu wählen?</div><ul><li>Ca. 2–3 Sekunden oder ca. 50 m Abstand halten, denn wenn mich ein Fahrzeug überholt, dann kann es sich vor mir einordnen.</li></ul><div class=\"zmod\">Technisches — Fragen & Antworten</div><div class=\"zq\">Welche Kontrollen führen Sie bei Reifen vor Fahrtantritt durch?</div><ul><li>Die Verformung des Reifens durch Sichtkontrolle prüfen · die Gleichmäßigkeit der Laufflächenabnützung</li></ul><div class=\"zq\">Wie viel mm muss die Profiltiefe mindestens haben?</div><ul><li>Mind. 2 mm</li></ul><div class=\"zq\">Welche Nachteile und Gefahren kann es beim Fahren mit zu geringem Reifendruck geben?</div><ul><li>Überhitzung des Reifens durch starkes Walken · Reifenbrand oder -platzer · Erhöhung des Kraftstoffverbrauches</li></ul><div class=\"zq\">Wo darf man einen Radwechsel durchführen und was muss man beachten?</div><ul><li>Es ist ein geeigneter Platz zu suchen, nicht auf der Fahrbahn! · Alarmblinkanlage einschalten · Warnweste anziehen · Feststellbremse anziehen, Gang einlegen, Unterlegkeile vorlegen · Radmuttern lockern · Fahrzeug abheben · Radmuttern abschrauben · Rad oder Räder abnehmen · Reserverad aufsetzen (beim Aufsetzen der Zwillingsräder ist auf den Ventilzugang zu achten) · Radmuttern anschrauben · Radmuttern kreuzweise festziehen</li></ul><div class=\"zq\">Was ist eine Feststellbremse?</div><ul><li>Es ist eine von der Betriebsbremse unabhängig zu betätigende Bremsanlage, mit der das Abrollen des Fahrzeuges dauernd verhindert werden kann.</li></ul><div class=\"zq\">Was können Sie an der Betriebsbremse bei stehendem Fahrzeug überprüfen?</div><ul><li>Den Leerweg, die Dichtheit, die Bremslichter und das Mehrkreisschutzventil</li></ul><div class=\"zq\">Was ist bei einer Lenkung regelmäßig zu kontrollieren?</div><ul><li>Der Flüssigkeitsstand im Ölbehälter der hydraulischen Lenkhilfe · das Lenkungsspiel, bei laufendem Motor darf kein deutlicher Leerweg spürbar sein · die Leichtgängigkeit · der Selbstrücklauf</li></ul><div class=\"zq\">Ihr LKW zieht beim Geradeausfahren nach einer Seite. Welche Ursachen kann dies haben?</div><ul><li>Zu geringer Reifendruck in einem der beiden Vorderreifen · die Lenkgeometrie ist verstellt · starker Seitenwind</li></ul><div class=\"zq\">Welche Wartungs- und Kontrollarbeiten kann der Lenker an der Batterie selbst durchführen?</div><ul><li>Kontrolle des Flüssigkeitsstandes · Säubern der Pole · Kabelanschlüsse und Batteriehalterungen auf festen Sitz prüfen</li></ul><div class=\"zq\">Welche Auswirkungen kann eine rutschende Kupplung auf den Fahrbetrieb haben?</div><ul><li>Die Beschleunigung des Fahrzeuges wird schlechter · die Motorbremsung wird geringer · die Wirkung der Motorstaubremse ist geringer</li></ul><div class=\"zq\">Was kann der Lenker an der Kupplung überprüfen?</div><ul><li>Den Leerweg (Totgang) · das vollständige Lösen · das vollständige Verbinden</li></ul><div class=\"zq\">Welche Kaltstarteinrichtungen können bei einem Dieselmotor eingebaut sein?</div><ul><li>Flammstartanlage · Heizflansch · Vorglühanlage</li></ul><div class=\"zq\">Woran können Sie eine Störung in der Kaltstarteinrichtung des Dieselmotors erkennen?</div><ul><li>Motor springt nicht an · beim Verglühen leuchtet die Vorglüh-Kontrolllampe nicht auf.</li></ul><div class=\"zq\">Woran können Sie während der Fahrt Mängel im Schmiersystem des Dieselmotors erkennen?</div><ul><li>Am Ölmanometer oder an der Öldruckkontrolllampe</li></ul><div class=\"zq\">Während der Fahrt leuchtet die Öldruckkontrolllampe auf. Wie werden Sie sich verhalten?</div><ul><li>Ich halte an und stelle den Motor ab · wenn genügend Motoröl in der Ölwanne ist, lasse ich den LKW abschleppen.</li></ul><div class=\"zq\">Während der Fahrt leuchtet die Ladekontrollleuchte auf. Was schließen Sie daraus und wie verhalten Sie sich?</div><ul><li>Strom wird nur mehr aus der Batterie entnommen · die Batterie wird nicht mehr geladen · ich kontrolliere den Keilriemen · wenn der Keilriemen nicht gerissen ist, fahre ich zur nächsten Werkstätte.</li></ul><div class=\"zq\">Wie können Sie während der Fahrt feststellen, dass die Motorkühlung nicht einwandfrei funktioniert?</div><ul><li>Das Fernthermometer zeigt in den roten Bereich · eine zusätzliche Kühlerkontrolllampe beim Fernthermometer leuchtet auf.</li></ul><div class=\"zq\">Wie verhalten Sie sich, wenn Sie erkennen, dass die Motorkühlung ausgefallen ist?</div><ul><li>Ich werde anhalten und kontrollieren, ob der Keilriemen richtig gespannt ist · ich kontrolliere, ob genügend Kühlflüssigkeit im Ausgleichsbehälter ist.</li></ul><div class=\"zq\">Wie können Sie während der Fahrt feststellen, dass die Betriebsbremse defekt ist?</div><ul><li>Die Bremswarnleuchte leuchtet auf · ich bemerke eine verringerte oder fehlende Bremswirkung.</li></ul><div class=\"zq\">Wie verhalten Sie sich, wenn Sie einen Defekt an der Betriebsbremse feststellen?</div><ul><li>Ich halte an und führe eine Standbremsprobe durch.</li></ul><div class=\"zq\">Welche Vorteile hat die Luftfederung?</div><ul><li>Schonung des Ladegutes · beim Kurvenfahren bleibt die Ladefläche nahezu waagrecht.</li></ul><div class=\"zq\">Was können Sie an der Luftfederung eines LKW überprüfen?</div><ul><li>Den Zustand der Federbälge durch Sichtkontrolle · die Dichtheit durch Abhorchen · das Gestänge der Niveauregelventile</li></ul><div class=\"zq\">Welche Ursachen kann blauer Auspuffrauch haben?</div><ul><li>Hoher Verschleiß am Motor · Ölabstreifring gebrochen · Dichtring undicht</li></ul><div class=\"zq\">Welche Ursachen kann schwarzer Auspuffrauch haben?</div><ul><li>Luftfilter stark verschmutzt · Treibstoffüberschuss · Motor überlastet</li></ul><div class=\"zq\">Welche Ursachen kann weißer Auspuffrauch haben?</div><ul><li>Wasserdampf nach Kaltstart · Zylinderkopfdichtung undicht, defekt · Steg- oder Büchsenriss im Motorzylinder</li></ul><div class=\"zq\">Wozu dient das Mehrkreisschutzventil bei einer Druckluftbremse?</div><ul><li>Zur Drucksicherung von Nebenverbrauchern · zur Erhaltung des Sicherungsdruckes bei Ausfall eines Kreises der Betriebsbremsanlage</li></ul><div class=\"zq\">Welche Aufgabe hat das Mehrkreisschutzventil einer Druckluftbremse?</div><ul><li>Es sichert den Druck in den anderen Vorratskreisen, wenn ein Vorratskreis ausfällt.</li></ul><div class=\"zq\">Was verstehen Sie unter einer ALB-Regelung bei einer Druckluftbremsanlage?</div><ul><li>Eine Anlage, welche die Bremskraft der Achsen nach dem Beladungszustand automatisch regelt.</li></ul><div class=\"zq\">Wie durchfahren Sie eine Kurve mit dem LKW?</div><ul><li>Ich werde vor der Kurve die Geschwindigkeit anpassen und erst im Kurvenauslauf beschleunigen · in der Kurve mache ich kurze Kontrollblicke in den Rückspiegel.</li></ul><div class=\"zq\">Sie fahren mit Ihrem LKW in eine Kurve. Welche Faktoren erhöhen die Kippgefahr?</div><ul><li>Eine verrutschende Ladung · eine hohe Schwerpunktlage · ruckartiges Lenken · halbvoller Wassertank</li></ul><div class=\"zq\">Wonach richten Sie die Fahrgeschwindigkeit in einer engen Kurve?</div><ul><li>Nach dem Kurvenradius und der Querneigung der Fahrbahn · nach der Höhe des Gesamtschwerpunktes des LKW · nach dem Fahrbahnzustand</li></ul><div class=\"zq\">Sie befahren mit Ihrem LKW eine längere Gefällestrecke. Wann verwenden Sie die Betriebsbremse?</div><ul><li>Vor und während des Zurückschaltens in einen niedrigen Gang · zum Anbremsen vor Kurven · beim Anbremsen bis zum Stillstand</li></ul><div class=\"zq\">Sie fahren mit Ihrem LKW auf einer Freilandstraße mit einem Gefälle von 9 %. Wie verhalten Sie sich in dieser Situation?</div><ul><li>Ich werde rechtzeitig auf einen niedrigen Gang schalten, damit ich mit der Motorbremswirkung meine Geschwindigkeit halten kann · ich bremse mit der Motorstaubremse auch über eine längere Strecke · falls vorhanden, bremse ich mit der Wirbelstrombremse.</li></ul><div class=\"zq\">Sie befahren mit Ihrem LKW eine Steigung. Wann müssen Sie zurückschalten?</div><ul><li>Wenn die Motordrehzahl trotz Vollgas unter den „grünen Bereich“ des Drehzahlmessers zu sinken droht.</li></ul><div class=\"zq\">Sie erkennen, dass sich hinter Ihrem LKW eine lange Kolonne gebildet hat. Wie werden Sie sich im Nichteinsatzfall verhalten?</div><ul><li>Ich sollte an geeigneter Stelle anhalten und die Fahrzeuge hinter mir vorbeizulassen · ich werde auf die Fahrzeuge hinter mir besonders achten, um bei riskanten Überholmanövern rasch reagieren zu können.</li></ul><div class=\"zq\">Wie erkennen Sie, dass nicht genügend Motoröl vorhanden ist?</div><ul><li>Aufleuchten der Ölstandskontrolleleuchte, wenn eine vorhanden ist · bei abgestelltem Motor durch den Ölmessstab</li></ul><div class=\"zq\">Welche Gefahr besteht, wenn Sie sich bei aufleuchtender Öldruckkontrollleuchte falsch verhalten?</div><ul><li>Bei Weiterfahrt kann es zu einem Motorschaden kommen · bei einem Motorschaden kann das Fahrzeug ins Schleudern kommen · wenn das Fahrzeug auf der Fahrbahn abgestellt wird und nicht abgesichert ist, kann es zu einem Auffahrunfall kommen.</li></ul><div class=\"zq\">Was ist beim Überholen von Fahrzeugen zu beachten?</div><ul><li>Den größeren Platzbedarf berücksichtigen · unter Umständen mit längeren Bremswegen rechnen · rechtzeitig zurückschalten · mit einer geringeren Beschleunigung rechnen · den längeren Überholweg und die größere Überholsichtweite berücksichtigen · den Seitenabstand beachten, im Besonderen beim Überholen von Rad- und Mopedfahrern</li></ul><div class=\"zq\">Was verstehen Sie unter einer Druckluftbremsanlage?</div><ul><li>Eine Bremsanlage, bei der die Bremskraft durch Druckluft erzeugt wird.</li></ul><div class=\"zq\">Was kann die Ursache sein, wenn der Kompressor zu wenig Luft fördert?</div><ul><li>Luftfilter kann verlegt sein · Keilriemen können rutschen · der Kompressor kann Kompressionsverluste haben.</li></ul><div class=\"zq\">Welche Aufgabe hat der Lufttrockner einer Druckluftbremse?</div><ul><li>Der vom Kompressor geförderten Luft die Feuchtigkeit zu entziehen.</li></ul><div class=\"zq\">Wie können Sie im Winter die Gefahr des Einfrierens einer Druckluftbremsanlage verringern?</div><ul><li>Die Frostschutzeinrichtung auf Winterbetrieb stellen · die Luftbehälter täglich entwässern.</li></ul><div class=\"zq\">Die Warnleuchte für die Betriebsbremsanlage leuchtet auf. Wie viele Bremsungen können Sie noch durchführen?</div><ul><li>Noch mind. 4 Vollbremsungen</li></ul><div class=\"zq\">Der Vorratsdruck einer Druckluftbremse fällt bei einer Vollbremsung um mehr als 0,7 bar ab. Welche Ursachen kann dies haben?</div><ul><li>Die Bremsbeläge können abgenutzt sein · die Vorratsbehälter können stark eingebeult sein · Wasser kann in den Vorratsbehältern sein.</li></ul><div class=\"zmod\">Feuerwehrspezifisches — Fragen & Antworten</div><div class=\"zq\">Worauf ist beim Fahren mit Tanklöschfahrzeugen betreffend des Wassertankinhaltes zu beachten?</div><ul><li>Mit vollem bzw. leerem Tank fahren, da es bei Kurvenfahrt und Bremsmanöver mit halbvollem Wassertank durch Schwabbelbewegungen zu unkontrollierbaren Schwerpunktverlagerungen kommen kann · sollte die Rückfahrt vom Einsatz mit teilgefülltem Wassertank angetreten werden, ist mit besonderer Vorsicht bis zur nächsten Füllmöglichkeit zu fahren · hohen Schwerpunkt beachten.</li></ul><div class=\"zq\">Wie sind Feuerwehrfahrzeuge verkehrs- und betriebssicher zu erhalten und wie ist dies zu überprüfen bzw. zu dokumentieren?</div><ul><li>Durchführung von Probefahrten mind. alle 14 Tage über mind. 10 km mit anschließendem Eintrag ins Fahrtenbuch und Fahrzeugkontrolle anhand der Checkliste.</li></ul><div class=\"zq\">Wie (mit welchen Geräten) sind Einsatzstellen abzusichern?</div><ul><li>Abhängig von der Witterung und den Straßenverhältnissen · im Ortsgebiet: 50 m · auf Freilandstraßen: 150–250 m · auf Autobahnen: 250–400 m. Zusätzlich zur StVO-Ausrüstung (Pannendreieck) stehen zur Verfügung: Verkehrsleitkegel · Triopan-Faltsignale · orange Blitzleuchten · hochreflektierende Warnüberwürfe · Verkehrsleiteinrichtungen am Feuerwehrfahrzeug · Verkehrsregler mit spezieller Ausrüstung (Anhaltestab, Einsatzbekleidung, Warnüberwurf).</li></ul><div class=\"zq\">Wo sind Einsatzstellen abzusichern (Kurven, Kuppen)?</div><ul><li>In Kurven und auf in zwei Richtungen befahrenen Straßen: Gegenverkehr sichern · vor Kuppen in ausreichendem Abstand sichern.</li></ul><div class=\"zq\">Was ist nach der Rückfahrt zu tun?</div><ul><li>Wiederherstellen der Einsatzbereitschaft · Reinigung des Fahrzeuges · Führen des Fahrtenbuches · Kontrollen am Fahrzeug · Einrückmeldung</li></ul><div class=\"zq\">Welche Kontrollen sind vor jeder Ausfahrt durchzuführen?</div><ul><li>Einsatzbereitschaft des Fahrzeuges muss immer gegeben sein · Fahrtauglichkeit des Fahrers muss gegeben sein · Fahrzeug nicht überladen · Fahrzeugkontrolle · Abstecken der Versorgungsleitungen und der Abgasleitung · Zuteilung der Mannschaft abwarten (Fahrer ist nicht GK, GK ist nicht Fahrer) · Mindestbesatzung · Öffnen der Garagentore bis zum Anschlag / Sichern des Tores · Anlegen der Sicherheitsgurte · Fahrzeugtüren schließen · Abfahrt auf Weisung des Gruppenkommandanten</li></ul><div class=\"zq\">Was ist bei der Auswahl des Aufstellungsortes bei der Einsatzstelle zu beachten?</div><ul><li>Gefahrenbereich meiden · Fluchtrichtung · auf der Straßenseite der Einsatzstelle · nicht im Trümmerschatten · Rückzugsmöglichkeiten</li></ul><div class=\"zq\">Aufgabenteilung Lenker – Fahrzeugkommandant</div><ul><li>Lenker: Betätigen der Warnsignale · konzentriere dich auf die Fahrt und nicht auf Funkmeldungen · Fahrgeschwindigkeit den Verhältnissen anpassen · Fahrverhalten des Fahrzeuges (hoher Schwerpunkt, Wassertank, Witterung). — Fahrzeugkommandant: Prüfen der Fahrtauglichkeit · Einweisen · Sichern · Funkverkehr · Anfahrtstrecke bekannt geben · Fahrzeugruhe.</li></ul><div class=\"zmod\">Rechtliches — Fragen & Antworten</div><div class=\"zq\">Was versteht man unter einem Feuerwehrfahrzeug, was unter einem Einsatzfahrzeug? Ist ein VW-Golf, der auf eine Feuerwehr zugelassen ist, ein Feuerwehrfahrzeug?</div><ul><li>Ein Feuerwehrfahrzeug ist ein nach Bauart und Ausrüstung ausschließlich oder vorwiegend zur Verwendung für Feuerwehren bestimmtes Fahrzeug. Ein VW Golf, der nicht entsprechend umgebaut ist, gilt nicht als Feuerwehrfahrzeug im Sinne des KFG. Ein Fahrzeug gilt als Einsatzfahrzeug, wenn entweder Blaulicht oder Folgetonhorn eingeschaltet sind, für die Dauer der Verwendung eines dieser Signale.</li></ul><div class=\"zq\">Ist der Lenker eines Feuerwehrfahrzeuges auch außerhalb von Einsatzfahrzeugen an bestimmte Verkehrsvorschriften nicht gebunden?</div><ul><li>Ja, bei „Allgemeines Fahrverbot“, „Einfahrt verboten“ und „Vorgeschriebene Fahrtrichtung“, wenn Ausnahmen für andere Kraftfahrzeuge und Fuhrwerke auf Zusatztafeln angebracht sind.</li></ul><div class=\"zq\">Wie viele Personen dürfen Sie in einem Feuerwehrfahrzeug mitnehmen?</div><ul><li>Die im Zulassungsschein eingetragene Zahl ist maßgeblich; nur bei Fahrten zu Orten eines dringenden Einsatzes und auf Rückfahrten von solchen Orten mit Feuerwehrfahrzeugen darf diese Anzahl überschritten werden (§ 106 Abs. 3 KFG i.V.m. § 107 Abs. 3).</li></ul><div class=\"zq\">Unter welchen Voraussetzungen müssen Kinder in Feuerwehrfahrzeugen angegurtet werden?</div><ul><li>Bei Fahrzeugen bis 3,5 to hzl. Gesamtgewicht muss der Lenker darauf achten, dass Kinder unter 12, die kleiner als 1,50 m sind, auch in Feuerwehrfahrzeugen angegurtet werden, sofern diese mit Sicherheitsgurten ausgerüstet sind. Ausnahmen: besondere Verkehrslage, die den Nichtgebrauch rechtfertigt, oder bei Beförderung bei Einsatzfahrten mit Blaulicht oder Folgetonhorn.</li></ul><div class=\"zq\">Müssen sich Erwachsene im Feuerwehrfahrzeug angurten?</div><ul><li>Ja, wenn der Sitzplatz mit einem Sicherheitsgurt ausgerüstet ist. Ausnahme: bei Einsatzfahrzeugen (Blaulicht oder Folgetonhorn eingeschaltet), wenn der Gebrauch des Sicherheitsgurtes mit dem Zweck der Fahrt unvereinbar ist (z. B. wenn im Fahrzeug schon Atemschutzausrüstung angelegt wird).</li></ul><div class=\"zq\">Ist der Lenker dafür verantwortlich, dass sich die übrigen Insassen angurten?</div><ul><li>Lenker und beförderte Personen sind je für sich zum Gebrauch des Sicherheitsgurtes verpflichtet, nur bei Kindern ist der Lenker dafür verantwortlich.</li></ul><div class=\"zq\">Dürfen Sie mit einem Feuerwehrfahrzeug in einer 30 km/h Zone mit 50 km/h oder mit 80 km/h fahren bzw. wie schnell darf man dort fahren?</div><ul><li>Bei Einsatzfahrten sind Feuerwehrfahrzeuge auf Fahrten zu Orten eines dringenden Einsatzes nicht an Geschwindigkeitsbeschränkungen gemäß StVO oder KDV gebunden. Die Fahrgeschwindigkeit ist jedoch den konkreten Verhältnissen anzupassen; auch der Grundsatz „Fahren auf Sicht“ ist zu beachten.</li></ul><div class=\"zq\">Dürfen bei Einsatzübungsfahrten Blaulicht und Folgetonhorn verwendet werden und Geschwindigkeiten überschritten werden?</div><ul><li>Ja, aber nur wenn es der Zweck der Einsatzübungsfahrt erfordert und sonst in geeigneter Weise für die Verkehrssicherheit vorgesorgt ist (z. B. Absicherung der Strecke durch Streckenposten).</li></ul><div class=\"zq\">Hat ein Feuerwehrfahrzeug immer Vorrang?</div><ul><li>Nein, nur wenn Blaulicht oder Folgetonhorn eingeschaltet sind.</li></ul><div class=\"zq\">Wann dürfen Sie die Warnzeichen einschalten?</div><ul><li>Nur bei Gefahr im Verzug, z. B. bei Fahrten zum und vom Ort der dringenden Hilfeleistung oder zum Ort des sonstigen dringenden Einsatzes. Das Blaulicht darf aus Gründen der Verkehrssicherheit auch am Ort des Einsatzes verwendet werden.</li></ul><div class=\"zq\">Ist der Lenker eines Einsatzfahrzeuges an Verkehrsverbote oder Verkehrsbeschränkungen gebunden?</div><ul><li>Bei Einsatzfahrten (Blaulicht oder Folgetonhorn) ist er grundsätzlich nicht an Verkehrsverbote oder Verkehrsbeschränkungen gebunden; er darf hierbei jedoch nicht Personen gefährden oder Sachen beschädigen. Bei rotem Licht darf man nur in eine Kreuzung einfahren, wenn man vorher anhält und sich überzeugt, dass hierbei nicht Menschen gefährdet oder Sachen beschädigt werden. Einbahnstraßen dürfen in der Gegenrichtung befahren werden, aber nur, wenn der Einsatzort anders nicht oder nicht in der gebotenen Zeit erreichbar ist oder wenn Ausnahmen für andere Kraftfahrzeuge oder Fuhrwerke bestehen.</li></ul><div class=\"zq\">Dürfen Sie als Einsatzfahrer gegen die Einbahn fahren?</div><ul><li>Nur, wenn der Einsatzort anders nicht oder nicht in der gebotenen Zeit erreichbar ist oder wenn Ausnahmen für andere Kraftfahrzeuge bestehen (§ 26 Abs. 3 StVO). — Zusatzfrage: Haben Sie dann Vorrang gegenüber entgegenkommenden Fahrzeugen? Ja. — Zusatzfrage: Wie haben sich die anderen Verkehrsteilnehmer zu verhalten? Platz machen.</li></ul><div class=\"zq\">Welche Probleme können auftauchen, wenn Sie als Einsatzfahrer unberechtigt gegen die Einbahn fahren?</div><ul><li>Verwaltungsstrafverfahren · Mitverschulden bei einem Unfall</li></ul><div class=\"zq\">In welcher Reihenfolge haben beim Zusammentreffen von verschiedenen Einsatzfahrzeugen diese Vorrang?</div><ul><li>Rettungsfahrzeuge · Fahrzeuge der Feuerwehr · Fahrzeuge des Sicherheitsdienstes · sonstige Einsatzfahrzeuge</li></ul><div class=\"zq\">Wie haben sich alle Straßenbenützer einem herannahenden Einsatzfahrzeug gegenüber zu verhalten?</div><ul><li>Platz machen, Vorrang geben</li></ul><div class=\"zq\">Müssen Sie als Einsatzfahrer bei einer Kreuzung mit Rotlicht anhalten?</div><ul><li>Ja, nur nach dem Anhalten und Überzeugen, dass niemand gefährdet wird, darf Rotlicht überfahren werden.</li></ul><div class=\"zq\">Oberlöschmeister Meier fährt mit Blaulicht zur Pizzeria, weil seine Pizza kalt wird. Hat er gegenüber anderen Verkehrsteilnehmern Vorrang?</div><ul><li>Ja, die Vorrangregelung knüpft nicht daran an, ob jemand zu Recht oder zu Unrecht Blaulicht oder Folgetonhorn eingeschaltet hat. — Zusatzfrage: Hat Oberlöschmeister Meier irgendwelche Konsequenzen zu befürchten? Ja, ein Verwaltungsstrafverfahren wegen Verstoßes gegen § 26 Abs. 1 KFG i.V.m. § 134 KFG; Mitverschulden im Falle eines Unfalls.</li></ul><div class=\"zq\">Hat der Einsatzfahrer auch Vorrang bei einer ampelgeregelten Kreuzung bei Rotlicht?</div><ul><li>Nein, in diesem Fall muss er anhalten und sich überzeugen, dass er niemanden gefährdet.</li></ul><div class=\"zq\">Wer ist schuld, wenn Sie als Einsatzfahrer bei Rot in die Kreuzung einfahren und es kommt zu einem Unfall?</div><ul><li>Der Einsatzfahrer; unter Umständen trifft den anderen ein Mitverschulden, wenn er zu spät gebremst hat oder zu schnell gefahren ist.</li></ul><div class=\"zq\">Welche Dokumente haben Sie beim Lenken eines Feuerwehrfahrzeuges der Klasse C mitzuführen?</div><ul><li>Den Feuerwehrführerschein und den Führerschein; beides ist auf Verlangen der Exekutive zur Überprüfung auszuhändigen (§ 14 Abs. 1 FSG).</li></ul><div class=\"zq\">Welche Alkoholbestimmungen gibt es für Feuerwehrfahrzeuge?</div><ul><li>Bis 7,5 t höchstzulässige Gesamtmasse: 0,5 ‰; über 7,5 t höchstzulässige Gesamtmasse: mit Feuerwehrführerschein 0,5 ‰; ohne Feuerwehrführerschein 0,1 ‰ (§ 32a Abs. 6 FSG).</li></ul><div class=\"zq\">Dürfen Sie mit einem Feuerwehrführerschein mehr als 8 Personen im Feuerwehrfahrzeug mitführen, obwohl Sie keinen Busführerschein (Lenkberechtigung der Klasse D) besitzen?</div><ul><li>Ja</li></ul><div class=\"zq\">Unter welchen Voraussetzungen dürfen mehr als 8 Personen in einem Feuerwehrfahrzeug befördert werden?</div><ul><li>Das Fahrzeug muss dafür laut Zulassungsschein geeignet sein, der Lenker muss entweder eine zivile Lenkberechtigung der Klasse D oder eine zivile Lenkberechtigung der Klasse B und zusätzlich einen Feuerwehrführerschein aufweisen (§ 1 Abs. 3 FSG).</li></ul><div class=\"zq\">Dürfen Sie mit einer zivilen Lenkberechtigung B und einem Feuerwehrführerschein einen zivilen LKW lenken?</div><ul><li>Nein</li></ul><div class=\"zq\">Dürfen Sie mit einem Feuerwehrfahrzeug ohne Vignette oder Go-Box eine mautpflichtige Autobahn befahren?</div><ul><li>Ja (Feuerwehrfahrzeuge, an denen Blaulicht angebracht ist, sind gemäß § 5 Abs. 1 Bundesstraßen-Mautgesetz 2002 von der Maupflicht ausgenommen).</li></ul><div class=\"zq\">Wie bzw. mit welchen Abständen sind Einsatzstellen abzusichern?</div><ul><li>Abhängig von der Witterung und den Straßenverhältnissen, im Ortsgebiet jedoch mindestens 50 m, auf Freilandstraßen 150 m bis 250 m und auf Autobahnen 250 m bis 400 m.</li></ul><div class=\"zq\">Was passiert mit Ihrem Feuerwehrführerschein, wenn Ihnen die zivile Lenkberechtigung entzogen wird?</div><ul><li>Wird für die Dauer der Entziehung ungültig (§ 32a Abs. 4 FSG).</li></ul>", "unterlagen": {"Ausbildung & Prüfung (OÖLFV-Original)": [["Ausbildungsplan Feuerwehrführerschein inkl. Lernunterlage „Fragenkatalog zur Vorbereitung auf das Prüfungsgespräch“ (6.11.002)", "6.11.002_AU_Ausbildungsplan_Feuerwehrfuehrerschein.pdf", "06_Organisation_und_Verwaltung/06.11_Feuerwehrfuehrerschein/6.11.002_AU_Ausbildungsplan_Feuerwehrfuehrerschein.pdf"], ["Richtlinie Führerscheinausbildung im Feuerwehrwesen (6.11.001)", "6.11.001_RL_Fuehrerscheinausbildung_im_Feuerwehrwesen.pdf", "06_Organisation_und_Verwaltung/06.11_Feuerwehrfuehrerschein/6.11.001_RL_Fuehrerscheinausbildung_im_Feuerwehrwesen.pdf"]], "Die 12 Fahrlektionen — Ausbildungsplan": [["Ausbildungsplan — Theoretische Ausbildung (12 Einheiten, Seite 1–2)", "6.11.002_AU_Ausbildungsplan_Feuerwehrfuehrerschein.pdf", "06_Organisation_und_Verwaltung/06.11_Feuerwehrfuehrerschein/6.11.002_AU_Ausbildungsplan_Feuerwehrfuehrerschein.pdf"], ["Ausbildungsplan — Praktische Ausbildung / Fahrlektionen (12 Einheiten, Seite 2)", "6.11.002_AU_Ausbildungsplan_Feuerwehrfuehrerschein.pdf", "06_Organisation_und_Verwaltung/06.11_Feuerwehrfuehrerschein/6.11.002_AU_Ausbildungsplan_Feuerwehrfuehrerschein.pdf"]], "5,5t-Lenkberechtigung (6.11.004)": [["AU Ausbildungsunterlagen Lenkberechtigung 5,5 Tonnen — Dienstanweisung, DO Allgemeine Informationen, Vortrag zur Ausbildung (44 Folien), Vortrag Infos, Gesetzblatt Verordnung 79, Nachweis Ausbildung, Prüfungsprotokoll, Vorlage L-Tafel (ZIP, 23 Dateien)", "6.11.004_AU_5_5_Tonnen_Lenkberechtigung.zip", "06_Organisation_und_Verwaltung/6.11.004_AU_5_5_Tonnen_Lenkberechtigung.zip"]]}, "stats": {"theorie_katalog": 127, "zusatz": 0, "praxis": 0, "karten": 84, "merkhilfen": 13, "unterlagen": 6}, "unterlagen_base": "https://www.ooelfv.at/downloadcenter/"};